# =====================================================================
# YARDIMCI FONKSİYONLAR
# =====================================================================

def clamp(v, lo, hi):
    return lo if v < lo else hi if v > hi else v


def lerp(a, b, t):
    return a + (b - a) * t


def dist(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)


def norm_dir(x1, y1, x2, y2):
    dx, dy = x2 - x1, y2 - y1
    d = math.hypot(dx, dy)
    if d < 1e-6:
        return 0.0, 0.0
    return dx / d, dy / d


def ease_out_cubic(t):
    t = clamp(t, 0.0, 1.0)
    return 1 - (1 - t) ** 3


def fmt_time(seconds):
    m = int(seconds) // 60
    s = int(seconds) % 60
    return f"{m:02d}:{s:02d}"


def fmt_num(n):
    n = int(n)
    return f"{n:,}".replace(",", ".")


def scale_col(c, k):
    return (int(clamp(c[0] * k, 0, 255)), int(clamp(c[1] * k, 0, 255)), int(clamp(c[2] * k, 0, 255)))


def mix_col(a, b, t):
    return (int(clamp(lerp(a[0], b[0], t), 0, 255)),
            int(clamp(lerp(a[1], b[1], t), 0, 255)),
            int(clamp(lerp(a[2], b[2], t), 0, 255)))


def lighten(c, t):
    return mix_col(c, (255, 255, 255), t)


def hue_col(h, s=0.72, v=1.0, steps=24):
    """Renk döngüsü (önbellek dostu olması için adımlara bölünür)."""
    h = (int(h * steps) % steps) / steps
    r, g, b = colorsys.hsv_to_rgb(h, s, v)
    return (int(r * 255), int(g * 255), int(b * 255))


def rot(px, py, ang, ox, oy):
    c, s = math.cos(ang), math.sin(ang)
    return (ox + px * c - py * s, oy + px * s + py * c)


def rot_pts(pts, ang, ox, oy):
    return [rot(x, y, ang, ox, oy) for x, y in pts]


def zigzag(x1, y1, x2, y2, segs, amp, rnd=random):
    pts = [(x1, y1)]
    dx, dy = x2 - x1, y2 - y1
    L = math.hypot(dx, dy) or 1.0
    nx, ny = -dy / L, dx / L
    for i in range(1, segs):
        f = i / segs
        off = rnd.uniform(-amp, amp)
        pts.append((x1 + dx * f + nx * off, y1 + dy * f + ny * off))
    pts.append((x2, y2))
    return pts


# =====================================================================
# FONT / METİN
# =====================================================================
_font_cache = {}
_text_cache = {}


def get_font(size, bold=False):
    size = int(size)
    key = (size, bold)
    f = _font_cache.get(key)
    if f is None:
        try:
            f = pygame.font.SysFont("segoeui,arial,helvetica,sans", size, bold=bold)
        except Exception:
            f = pygame.font.Font(None, size)
        _font_cache[key] = f
    return f


def _render(text, size, bold, color):
    key = (text, size, bold, color)
    img = _text_cache.get(key)
    if img is None:
        if len(_text_cache) > 900:
            _text_cache.clear()
        img = get_font(size, bold).render(text, True, color)
        _text_cache[key] = img
    return img


def draw_text(surf, text, pos, size=20, color=TEXT, bold=False,
              center=False, shadow=True, alpha=255, right=False):
    size = int(size)
    color = (int(color[0]), int(color[1]), int(color[2]))
    alpha = int(clamp(alpha, 0, 255))
    img = _render(text, size, bold, color)
    img.set_alpha(alpha)
    r = img.get_rect()
    px, py = int(pos[0]), int(pos[1])
    if center:
        r.center = (px, py)
    elif right:
        r.topright = (px, py)
    else:
        r.topleft = (px, py)
    if shadow:
        sh = _render(text, size, bold, (0, 0, 0))
        sh.set_alpha(alpha)
        surf.blit(sh, (r.x + 2, r.y + 2))
    surf.blit(img, r)
    return r


def text_width(text, size=20, bold=False):
    return get_font(size, bold).size(text)[0]


def wrap_text(text, size, max_w, bold=False):
    words = text.split(" ")
    lines, line = [], ""
    for w in words:
        test = (line + " " + w).strip()
        if text_width(test, size, bold) > max_w and line:
            lines.append(line)
            line = w
        else:
            line = test
    if line:
        lines.append(line)
    return lines


# =====================================================================
# GLOW / DISK / GÖLGE ÖNBELLEKLERİ  (performans için sprite kullanılır)
# =====================================================================
_glow_cache = {}
_disc_cache = {}
_shadow_cache = {}


def glow_sprite(r, color, level):
    key = (r, color, level)
    s = _glow_cache.get(key)
    if s is None:
        if len(_glow_cache) > 1400:
            _glow_cache.clear()
        s = pygame.Surface((r * 2, r * 2))
        s.fill((0, 0, 0))
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            pygame.draw.circle(s, scale_col(color, inten), (r, r), rad)
        _glow_cache[key] = s
    return s


_glow_cache_a = {}


def glow_sprite_alpha(r, color, level):
    """SAYDAM yüzeye basılabilen parlama.

    Normal parlama opak zemine TOPLAMALI basılır; saydam bir yüzeyde ise
    alfa 0 kaldığı için hiç görünmez. Burada alfa da yarıçapla birlikte
    sönüyor, böylece önbelleğe alınmış bir sprite'ın içindeki parlama,
    sprite dünyaya basıldığında yumuşak bir hâle olarak çıkıyor.
    """
    key = (r, color, level)
    s = _glow_cache_a.get(key)
    if s is None:
        if len(_glow_cache_a) > 900:
            _glow_cache_a.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        steps = int(min(26, max(5, r // 2 + 3)))
        k = level / 8.0
        for i in range(steps):
            f = i / (steps - 1)
            rad = max(1, int(r * (1 - f * 0.94)))
            inten = (f ** 2.3) * k
            # DİKKAT: renk TAM parlaklıkta, sönümleme YALNIZCA alfada.
            # Hem rengi hem alfayı sönümlersek katkı inten² olur ve hâle
            # neredeyse kaybolur (toplamalı sürümde katkı inten'dir).
            pygame.draw.circle(s, (color[0], color[1], color[2],
                                   int(clamp(255 * inten, 0, 255))), (r, r), rad)
        _glow_cache_a[key] = s
    return s


# Saydam bir ara yüzeye (simge / yaratık gövdesi önbelleği) çizerken açılır.
_GLOW_ON_ALPHA = False


def add_glow(surf, x, y, r, color, k=1.0):
    """Parlama. Opak zeminde toplamalı, saydam yüzeyde alfalı."""
    level = int(clamp(k, 0.0, 1.0) * 8 + 0.5)
    if level <= 0:
        return
    r = max(2, int(r) // 2 * 2)
    c = (int(color[0]), int(color[1]), int(color[2]))
    pos = (int(x - r), int(y - r))
    if _GLOW_ON_ALPHA:
        # Saydam yüzeyde NORMAL alfa karışımı kullanılır. Toplamalı karışım
        # alfaya değil doğrudan RGB'ye eklediği için gövdeyi beyaza boğuyordu.
        surf.blit(glow_sprite_alpha(r, c, level), pos)
    else:
        surf.blit(glow_sprite(r, c, level), pos,
                  special_flags=pygame.BLEND_RGB_ADD)


def disc_sprite(r, color, alpha):
    a = int(clamp(alpha, 0, 255)) // 16 * 16
    key = (r, color, a)
    s = _disc_cache.get(key)
    if s is None:
        if len(_disc_cache) > 1400:
            _disc_cache.clear()
        s = pygame.Surface((r * 2, r * 2), pygame.SRCALPHA)
        pygame.draw.circle(s, (color[0], color[1], color[2], a), (r, r), r)
        _disc_cache[key] = s
    return s


def blit_disc(surf, x, y, r, color, alpha):
    r = max(1, int(r))
    if r > 14:
        r = r // 4 * 4
    if alpha < 8:
        return
    sp = disc_sprite(r, (int(color[0]), int(color[1]), int(color[2])), alpha)
    surf.blit(sp, (int(x - r), int(y - r)))


def shadow_sprite(w):
    w = max(6, int(w) // 2 * 2)
    s = _shadow_cache.get(w)
    if s is None:
        s = pygame.Surface((w, max(4, w // 3)), pygame.SRCALPHA)
        pygame.draw.ellipse(s, (0, 0, 0, 95), s.get_rect())
        _shadow_cache[w] = s
    return s


def draw_bar(surf, rect, frac, color, bg=(28, 30, 44), border=PANEL_EDGE, radius=7):
    rect = pygame.Rect(rect)
    pygame.draw.rect(surf, bg, rect, border_radius=radius)
    frac = clamp(frac, 0.0, 1.0)
    w = int((rect.w - 4) * frac)
    if w > 2:
        inner = pygame.Rect(rect.x + 2, rect.y + 2, w, rect.h - 4)
        pygame.draw.rect(surf, color, inner, border_radius=max(2, radius - 2))
        hl = pygame.Rect(inner.x + 2, inner.y + 1, max(1, inner.w - 4), max(1, inner.h // 3))
        pygame.draw.rect(surf, lighten(color, 0.4), hl, border_radius=3)
    pygame.draw.rect(surf, border, rect, width=2, border_radius=radius)


