def _pet_blob(surf, cx, cy, rx, ry, col, hl=True):
    """Kontürlü, gövde + parlama katmanlı yumuşak elips (pet gövdesi/kafası)."""
    rx, ry = max(2.0, rx), max(2.0, ry)
    rect = pygame.Rect(0, 0, int(rx * 2 + 4), int(ry * 2 + 4))
    rect.center = (int(cx), int(cy))
    pygame.draw.ellipse(surf, OUTLINE, rect)
    inner = rect.inflate(-4, -4)
    pygame.draw.ellipse(surf, scale_col(col, 0.72), inner)
    top = pygame.Rect(inner.x + 1, inner.y + 1, max(2, inner.w - 2), max(2, int(inner.h * 0.80)))
    pygame.draw.ellipse(surf, col, top)
    if hl:
        pygame.draw.circle(surf, lighten(col, .55), (int(cx - rx * .35), int(cy - ry * .42)),
                           max(1, int(min(rx, ry) * .20)))


def _pet_eyes(surf, ex, ey, gap, er, face):
    for sd in (-1, 1):
        px_, py_ = int(ex + sd * gap), int(ey)
        pygame.draw.circle(surf, (250, 250, 255), (px_, py_), max(2, int(er)))
        pygame.draw.circle(surf, (18, 18, 28), (int(px_ + face * er * .35), py_), max(1, int(er * .58)))


def _pet_tri(surf, pts, col):
    pygame.draw.polygon(surf, OUTLINE, pts, 0)
    # kontür için biraz daha büyük çizim yerine iç renk küçük bir kaydırmayla
    cx = sum(p[0] for p in pts) / len(pts)
    cy = sum(p[1] for p in pts) / len(pts)
    inner = [(cx + (p[0] - cx) * .72, cy + (p[1] - cy) * .72) for p in pts]
    pygame.draw.polygon(surf, col, inner, 0)


def _pet_curve(surf, pts, w, col):
    """Yuvarlak uçlu kalın eğri (kuyruklar için)."""
    rr = max(1.5, w / 2.0)
    samples = []
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        n = max(1, int(math.hypot(x1 - x0, y1 - y0) / 1.5))
        for i in range(n + 1):
            k = i / n
            samples.append((x0 + (x1 - x0) * k, y0 + (y1 - y0) * k))
    for c_, rad in ((OUTLINE, rr + 1.5), (col, rr)):
        for px_, py_ in samples:
            pygame.draw.circle(surf, c_, (int(px_), int(py_)), max(1, int(round(rad))))


def draw_pet(surf, kind, x, y, r, t, face=1, moving=False, col=(200, 200, 200),
             acc=(255, 255, 255), shadow=True):
    """Bir peti (x, y) merkezli, r yarıçaplı çizer. face: -1 sol, +1 sağ.

    Hepsi pygame.draw ile üretilir — resim dosyası yok. Hem oyun dünyasında
    hem markette/menüde aynı fonksiyon kullanılır.
    """
    s = float(r)
    ph = t * (10.0 if moving else 2.4)
    bob = math.sin(ph) * s * (0.14 if moving else 0.06)
    fl = kind in ("ghost", "owl", "drone", "dragon")          # havada duranlar
    yy = y + bob - (s * 0.45 if fl else 0.0)
    if shadow:
        surf.blit(shadow_sprite(int(s * 2.2)), (int(x - s * 1.1), int(y + s * 0.62)))
    fx_ = face

    if kind in ("cat", "dog", "bunny"):
        # kuyruk
        if kind == "cat":
            sw = math.sin(t * 3.0) * s * .25
            pts = [(x - fx_ * s * .8, yy + s * .3), (x - fx_ * s * 1.35, yy - s * .1 + sw),
                   (x - fx_ * s * 1.35, yy - s * .8 + sw)]
            _pet_curve(surf, pts, max(3.0, s * .5), col)
        elif kind == "dog":
            sw = math.sin(t * 14.0) * s * .35
            pts = [(x - fx_ * s * .8, yy + s * .2), (x - fx_ * s * 1.3, yy - s * .5 + sw)]
            _pet_curve(surf, pts, max(3.0, s * .45), col)
        else:
            pygame.draw.circle(surf, OUTLINE, (int(x - fx_ * s * .9), int(yy + s * .25)), int(s * .34) + 2)
            pygame.draw.circle(surf, (250, 250, 255), (int(x - fx_ * s * .9), int(yy + s * .25)), max(2, int(s * .34)))
        # ayaklar
        for i, sd in enumerate((-1, 1)):
            step = math.sin(ph + i * math.pi) * s * .18 if moving else 0.0
            _pet_blob(surf, x + sd * s * .42 + step, yy + s * .78, s * .30, s * .20, scale_col(col, .85), hl=False)
        _pet_blob(surf, x, yy + s * .12, s * .95, s * .78, col)
        hx, hy = x + fx_ * s * .5, yy - s * .52
        # kulaklar
        if kind == "cat":
            for sd in (-1, 1):
                _pet_tri(surf, [(hx + sd * s * .52, hy - s * .28), (hx + sd * s * .78, hy - s * 1.02),
                                (hx + sd * s * .08, hy - s * .58)], col)
        elif kind == "dog":
            for sd in (-1, 1):
                _pet_blob(surf, hx + sd * s * .72, hy + s * .1, s * .26, s * .55, scale_col(col, .62), hl=False)
        else:
            for sd in (-1, 1):
                _pet_blob(surf, hx + sd * s * .30, hy - s * .95, s * .22, s * .72, col, hl=False)
                pygame.draw.ellipse(surf, acc, pygame.Rect(int(hx + sd * s * .30 - s * .09), int(hy - s * 1.25),
                                                            max(2, int(s * .18)), max(3, int(s * .8))))
        _pet_blob(surf, hx, hy, s * .78, s * .70, col)
        if kind == "dog":
            _pet_blob(surf, hx + fx_ * s * .28, hy + s * .2, s * .38, s * .28, acc, hl=False)
            pygame.draw.circle(surf, (28, 22, 24), (int(hx + fx_ * s * .42), int(hy + s * .13)), max(1, int(s * .10)))
        _pet_eyes(surf, hx + fx_ * s * .16, hy - s * .1, s * .30, s * .19, fx_)
        if kind != "dog":
            pygame.draw.circle(surf, acc, (int(hx + fx_ * s * .36), int(hy + s * .16)), max(1, int(s * .08)))

    elif kind == "slime":
        sq = math.sin(t * 5.0)
        w, h = s * (1.05 + 0.10 * sq), s * (0.82 - 0.10 * sq)
        _pet_blob(surf, x, yy + s * .35 + (s * .82 - h) * .5, w, h, col)
        _pet_eyes(surf, x + fx_ * s * .12, yy + s * .22, s * .32, s * .20, fx_)
        pygame.draw.circle(surf, acc, (int(x - s * .45), int(yy + s * .0)), max(1, int(s * .12)))

    elif kind == "ghost":
        add_glow(surf, x, yy, s * 1.9, col, .22)
        pygame.draw.circle(surf, OUTLINE, (int(x), int(yy - s * .1)), int(s * .95) + 2)
        wob = math.sin(t * 4.0) * s * .12
        pts = [(x - s * .95, yy - s * .1)]
        n = 5
        for i in range(n + 1):
            px_ = x - s * .95 + (s * 1.9) * i / n
            py_ = yy + s * .95 + (wob if i % 2 else -wob) * (1 if i % 2 else 1)
            if i % 2 == 0:
                py_ -= s * .28
            pts.append((px_, py_))
        pts.append((x + s * .95, yy - s * .1))
        pygame.draw.polygon(surf, OUTLINE, [(px_, py_ + (2 if py_ > yy else 0)) for px_, py_ in pts])
        pygame.draw.circle(surf, col, (int(x), int(yy - s * .1)), int(s * .95))
        inner = [(px_ * .98 + x * .02, py_ - 1) for px_, py_ in pts]
        pygame.draw.polygon(surf, col, inner)
        pygame.draw.circle(surf, lighten(col, .55), (int(x - s * .4), int(yy - s * .5)), max(1, int(s * .18)))
        for sd in (-1, 1):
            pygame.draw.ellipse(surf, (34, 36, 58), pygame.Rect(int(x + fx_ * s * .10 + sd * s * .34 - s * .13),
                                                                  int(yy - s * .3), max(2, int(s * .26)), max(3, int(s * .38))))
            pygame.draw.circle(surf, acc, (int(x + sd * s * .58), int(yy + s * .12)), max(1, int(s * .13)))

    elif kind == "owl":
        flap = math.sin(t * (14.0 if moving else 5.0))
        for sd in (-1, 1):
            ang = s * (.55 + .28 * flap)
            _pet_blob(surf, x + sd * s * 1.0, yy + s * .1 - ang * .3, s * .32, s * .62, scale_col(col, .8), hl=False)
        _pet_blob(surf, x, yy, s * .95, s * 1.05, col)
        pygame.draw.ellipse(surf, lighten(col, .55), pygame.Rect(int(x - s * .55), int(yy + s * .1), int(s * 1.1), int(s * .78)))
        for sd in (-1, 1):
            _pet_tri(surf, [(x + sd * s * .78, yy - s * .55), (x + sd * s * .62, yy - s * 1.25),
                            (x + sd * s * .18, yy - s * .8)], scale_col(col, .8))
        for sd in (-1, 1):
            ex = x + sd * s * .42
            pygame.draw.circle(surf, OUTLINE, (int(ex), int(yy - s * .28)), int(s * .40) + 2)
            pygame.draw.circle(surf, acc, (int(ex), int(yy - s * .28)), max(2, int(s * .40)))
            pygame.draw.circle(surf, (20, 18, 24), (int(ex + fx_ * s * .08), int(yy - s * .28)), max(1, int(s * .18)))
        _pet_tri(surf, [(x - s * .12, yy - s * .06), (x + s * .12, yy - s * .06), (x, yy + s * .20)], (240, 170, 60))

    elif kind == "drone":
        add_glow(surf, x, yy + s * .1, s * 1.5, acc, .18)
        spin = t * 40.0
        for sd in (-1, 1):
            cx_ = x + sd * s * 1.05
            pygame.draw.line(surf, OUTLINE, (x + sd * s * .5, yy), (cx_, yy - s * .35), 4)
            pygame.draw.line(surf, (98, 108, 130), (x + sd * s * .5, yy), (cx_, yy - s * .35), 2)
            dx_ = math.cos(spin + sd) * s * .62
            pygame.draw.line(surf, OUTLINE, (cx_ - dx_, yy - s * .42), (cx_ + dx_, yy - s * .42), 4)
            pygame.draw.line(surf, (206, 214, 232), (cx_ - dx_, yy - s * .42), (cx_ + dx_, yy - s * .42), 2)
        _pet_blob(surf, x, yy, s * .9, s * .68, col)
        pygame.draw.circle(surf, (14, 18, 28), (int(x + fx_ * s * .12), int(yy)), max(3, int(s * .38)))
        pygame.draw.circle(surf, acc, (int(x + fx_ * s * .12), int(yy)), max(2, int(s * .24 + math.sin(t * 6) * s * .05)))
        blink = 1.0 if int(t * 2.2) % 2 == 0 else 0.25
        pygame.draw.circle(surf, (255, int(90 + 90 * blink), 90), (int(x - fx_ * s * .55), int(yy - s * .38)), max(1, int(s * .10)))

    elif kind == "dragon":
        flap = math.sin(t * (12.0 if moving else 6.0))
        for sd in (-1, 1):
            wy = yy - s * .2 - flap * s * .5
            _pet_tri(surf, [(x + sd * s * .3, yy - s * .1), (x + sd * s * 1.55, wy - s * .5),
                            (x + sd * s * 1.15, yy + s * .35)], acc)
        sw = math.sin(t * 3.4) * s * .2
        pts = [(x - fx_ * s * .8, yy + s * .35), (x - fx_ * s * 1.4, yy + s * .55 + sw), (x - fx_ * s * 1.8, yy + s * .2 + sw)]
        _pet_curve(surf, pts, max(3.0, s * .42), col)
        _pet_blob(surf, x, yy + s * .15, s * .92, s * .82, col)
        pygame.draw.ellipse(surf, lighten(col, .5), pygame.Rect(int(x - s * .5), int(yy + s * .2), int(s * 1.0), int(s * .6)))
        hx, hy = x + fx_ * s * .55, yy - s * .5
        for sd in (-1, 1):
            _pet_tri(surf, [(hx + sd * s * .40, hy - s * .35), (hx + sd * s * .52, hy - s * 1.0),
                            (hx + sd * s * .05, hy - s * .55)], acc)
        _pet_blob(surf, hx, hy, s * .76, s * .66, col)
        _pet_blob(surf, hx + fx_ * s * .42, hy + s * .16, s * .34, s * .24, lighten(col, .35), hl=False)
        _pet_eyes(surf, hx + fx_ * s * .10, hy - s * .1, s * .30, s * .18, fx_)
        if int(t * 0.5) % 3 == 0 and (t * 0.5) % 1.0 < 0.35:      # ara sıra ateş üfler
            fxp = (hx + fx_ * s * 1.05, hy + s * .2)
            add_glow(surf, fxp[0], fxp[1], s * .9, acc, .6)
            pygame.draw.circle(surf, (255, 230, 150), (int(fxp[0]), int(fxp[1])), max(2, int(s * .22)))


def _pet_state_update(st, p, t):
    """Peti oyuncunun arkasında yumuşak takip ettirir (dt, çizim zamanından)."""
    dt = clamp(t - st["last"], 0.0, 0.05)
    st["last"] = t
    vx, vy = getattr(p, "vx", 0.0), getattr(p, "vy", 0.0)
    sp = math.hypot(vx, vy)
    if sp > 20:
        st["dirx"], st["diry"] = vx / sp, vy / sp
    dirx, diry = st.get("dirx", -1.0), st.get("diry", 0.0)
    gap = p.radius + 30
    tx = p.x - dirx * gap - diry * 14
    ty = p.y - diry * gap + dirx * 14 + 6
    dx, dy = tx - st["x"], ty - st["y"]
    if dx * dx + dy * dy > 640 * 640:            # portal / ışınlanma: yanına atla
        st["x"], st["y"] = tx, ty
        dx = dy = 0.0
    else:
        k = 1.0 - math.exp(-dt * 5.0)
        st["x"] += dx * k
        st["y"] += dy * k
    st["moving"] = math.hypot(dx, dy) > 7
    if abs(dx) > 4:
        st["face"] = 1 if dx > 0 else -1


def draw_run_pet(world, run, t):
    """Kuşanılmış peti dünya yüzeyine çizer (ayarlardan kapatılabilir)."""
    if not CFG.get("pet_show", True):
        return
    p = run.player
    if not p.alive:
        return
    pid = getattr(run, "_pet_id", "?")
    if pid == "?":
        try:
            pid = run.save.equipped_cosmetic_id("pet")
        except Exception:
            pid = None
        run._pet_id = pid
        run._pet = None
    pet = PET_BY_ID.get(pid) if pid else None
    if not pet:
        return
    st = getattr(run, "_pet", None)
    if st is None:
        st = run._pet = {"x": p.x - 40.0, "y": p.y + 8.0, "last": t, "face": 1, "moving": False}
    _pet_state_update(st, p, t)
    draw_pet(world, pet["kind"], st["x"], st["y"], 11, t, face=st["face"], moving=st["moving"],
             col=pet["color"], acc=pet["accent"])


# ---- SİLAH GÖRSELLERİ (AÇIK / KISIK / KAPALI) ------------------------------
def weapon_fx_pct():
    """EŞYA EFEKTİ görünürlüğü, 0-100 arası tam sayı (oyuncu ayarı)."""
    v = CFG.get("weapon_fx", WEAPON_FX_DEFAULT)
    if isinstance(v, str):                       # çok eski kayıt
        v = WEAPON_FX_LEGACY.get(v, WEAPON_FX_DEFAULT)
    try:
        return int(clamp(int(round(float(v))), 0, 100))
    except (TypeError, ValueError):
        return WEAPON_FX_DEFAULT


def set_weapon_fx_pct(v):
    """Ayarı yazar (0-100 arasına kırpılır) ve değeri geri döndürür."""
    CFG["weapon_fx"] = int(clamp(int(round(float(v))), 0, 100))
    return CFG["weapon_fx"]


def weapon_fx_mode():
    """Eski üç kademeli ad — kodun geri kalanıyla uyum için."""
    v = weapon_fx_pct()
    if v <= 0:
        return "off"
    return "full" if v >= 100 else "dim"


def _wfx_begin(world, cam, need=True):
    """Efekt katmanı çizilmeden ÖNCE görüntüyü saklar (kısık görünürlükte).

    %100'de hiçbir şey saklanmaz (ek maliyet yok), %0'da katman zaten hiç
    çizilmez. Arada kalan her değerde eski görüntü saklanır ve katmanın
    üstüne o oranda geri basılır — efekt o kadar soluklaşır.

    need=False: çizilecek silah yok — pahalı ekran kopyası hiç alınmaz."""
    if not need:
        return None
    pct = weapon_fx_pct()
    if pct >= 100 or pct <= 0:
        return None
    try:
        clip = cam.clip(world.get_rect())
        return world.subsurface(clip).copy(), clip.topleft, pct
    except Exception:
        return None


def _wfx_end(world, snap):
    """Saklanan eski görüntüyü yarı saydam basar: efekt o oranda soluklaşır."""
    if snap is None:
        return
    img, pos, pct = snap
    img.set_alpha(int(clamp(255 * (1.0 - pct / 100.0), 0, 255)))
    world.blit(img, pos)


def _player_cosmetic(p, slot):
    cm = getattr(p, "cosmetics", None)
    if not cm:
        return None
    return COSMETIC_BY_ID.get(cm.get(slot))


def draw_cosmetic_cape(surf, p, px, py, t):
    """Pelerin — gövdenin ARKASINDA çizilir, harekete göre dalgalanır."""
    item = _player_cosmetic(p, "cape")
    if not item:
        return
    r = p.radius
    ax, ay = p.aim_dir
    bx, by = -ax, -ay
    if abs(bx) < 1e-3 and abs(by) < 1e-3:
        bx, by = 0.0, 1.0
    nx, ny = -by, bx
    col, acc = item["color"], item["accent"]
    if item["id"] == "wings_angelic":
        # MELEK KANADI: her kanat üç sıra tüyden oluşur (uzun uçuş tüyleri,
        # orta sıra, omuzdaki kısa örtü tüyleri). Kanatlar birlikte çırpar,
        # arkalarında yumuşak bir hale ve süzülen tüy parçacıkları bırakır.
        flap = math.sin(t * 5.0)
        open_amt = 0.92 + flap * 0.22          # çırpma: açılıp kapanma
        base_ang = math.atan2(by, bx)
        sx, sy = px + bx * r * 0.28, py + by * r * 0.28
        add_glow(surf, sx + bx * r * 0.5, sy + by * r * 0.5, r * 2.2, acc,
                 .26 + .08 * math.sin(t * 3))

        def feather(cx0, cy0, ang_, length, width, fill, edge):
            """Tek bir tüy: uçta sivrilen, dipte yuvarlak bir yaprak."""
            dxf, dyf = math.cos(ang_), math.sin(ang_)
            nxf, nyf = -dyf, dxf
            pts = [
                (cx0, cy0),
                (cx0 + dxf * length * 0.35 + nxf * width, cy0 + dyf * length * 0.35 + nyf * width),
                (cx0 + dxf * length * 0.78 + nxf * width * 0.72,
                 cy0 + dyf * length * 0.78 + nyf * width * 0.72),
                (cx0 + dxf * length, cy0 + dyf * length),
                (cx0 + dxf * length * 0.78 - nxf * width * 0.52,
                 cy0 + dyf * length * 0.78 - nyf * width * 0.52),
                (cx0 + dxf * length * 0.35 - nxf * width * 0.62,
                 cy0 + dyf * length * 0.35 - nyf * width * 0.62),
            ]
            pygame.draw.polygon(surf, OUTLINE, [(a + bx, b + by) for a, b in pts])
            pygame.draw.polygon(surf, fill, pts)
            pygame.draw.polygon(surf, edge, pts, 1)
            # tüy sapı
            pygame.draw.line(surf, edge, (cx0 + dxf * length * 0.12, cy0 + dyf * length * 0.12),
                             (cx0 + dxf * length * 0.92, cy0 + dyf * length * 0.92), 1)

        base_white = lighten(col, 0.42)
        for side in (-1, 1):
            # --- 1. sıra: uzun uçuş tüyleri (en arkada) ---
            for i in range(5):
                f = i / 4.0
                a = base_ang + side * (0.42 + open_amt * (0.26 + f * 0.62))
                L = r * (2.55 - f * 0.55)
                feather(sx, sy, a, L, r * 0.26, base_white, scale_col(acc, 0.85))
            # --- 2. sıra: orta tüyler ---
            for i in range(4):
                f = i / 3.0
                a = base_ang + side * (0.50 + open_amt * (0.22 + f * 0.52))
                L = r * (1.62 - f * 0.34)
                feather(sx, sy, a, L, r * 0.24, lighten(col, 0.62), scale_col(acc, 0.7))
            # --- 3. sıra: omuzdaki kısa örtü tüyleri ---
            for i in range(3):
                f = i / 2.0
                a = base_ang + side * (0.58 + open_amt * (0.18 + f * 0.40))
                L = r * (0.92 - f * 0.18)
                feather(sx, sy, a, L, r * 0.22, WHITE, acc)
            # omuz eklemi
            jx, jy = sx + math.cos(base_ang + side * 0.55) * r * 0.30,                      sy + math.sin(base_ang + side * 0.55) * r * 0.30
            pygame.draw.circle(surf, OUTLINE, (int(jx), int(jy)), max(3, int(r * 0.20)))
            pygame.draw.circle(surf, WHITE, (int(jx), int(jy)), max(2, int(r * 0.16)))
            pygame.draw.circle(surf, acc, (int(jx), int(jy)), max(2, int(r * 0.16)), 1)

        # süzülen tüy parçacıkları
        for i in range(3):
            ph = (t * 0.5 + i * 0.33) % 1.0
            fxp = sx + bx * r * (0.7 + ph * 1.5) + nx * math.sin(t * 1.6 + i * 2.1) * r * 1.1
            fyp = sy + by * r * (0.7 + ph * 1.5) + ny * math.sin(t * 1.6 + i * 2.1) * r * 1.1
            pygame.draw.circle(surf, lighten(acc, 0.5), (int(fxp), int(fyp)),
                               max(1, int(2.4 * (1.0 - ph))))
    else:
        sway = math.sin(t * 4.5 + px * 0.02) * 7
        base_x, base_y = px + bx * r * 0.25, py + by * r * 0.25
        top_l = (base_x + nx * r * 0.85, base_y + ny * r * 0.85)
        top_r = (base_x - nx * r * 0.85, base_y - ny * r * 0.85)
        tip_l = (top_l[0] + bx * (30 + sway), top_l[1] + by * (30 + sway))
        tip_r = (top_r[0] + bx * (30 - sway), top_r[1] + by * (30 - sway))
        mid = (base_x + bx * (34 + sway * 0.5), base_y + by * (34 + sway * 0.5))
        pts = [top_l, tip_l, mid, tip_r, top_r]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, acc, pts, 2)
        if item["id"] == "cape_shadow":
            add_glow(surf, mid[0], mid[1], r * 1.5, acc, .3)
        elif item["id"] == "cape_royal":
            pygame.draw.line(surf, acc, top_l, mid, 1)
            pygame.draw.line(surf, acc, top_r, mid, 1)


def draw_cosmetic_hat(surf, p, px, py, t):
    """Şapka — kafanın ÜSTÜNDE, gövdeden sonra çizilir.

    Her şapkanın kendine ait bir silueti var; hiçbiri "genel görünüm"e
    düşmüyor. Ortak görsel dil: koyu bir taban gölgesi (OUTLINE), ana renk,
    sol üstten gelen ışık için lighten() ile bir parlama ve accent rengiyle
    küçük bir detay (taş, düğme, kor, pırıltı).
    """
    item = _player_cosmetic(p, "hat")
    if not item:
        return
    r = p.radius
    col, acc = item["color"], item["accent"]
    dark = scale_col(col, 0.62)
    lite = lighten(col, 0.34)

    if item["id"] == "cap_red":
        # Klasik beyzbol şapkası: siperlik tacın ön kenarından çıkar ve
        # nişan yönüne döner (kopuk bir yuvarlak değil, gerçek bir siperlik).
        cy = py - r * 0.58
        ax, ay = p.aim_dir
        ang = math.atan2(ay, ax)
        ca, sa = math.cos(ang), math.sin(ang)
        visor_local = [(r * 0.05, -r * 0.52), (r * 0.78, -r * 0.42), (r * 1.20, -r * 0.15),
                       (r * 1.20, r * 0.15), (r * 0.78, r * 0.42), (r * 0.05, r * 0.52)]
        vpts = [(px + lx * ca - ly * sa, cy + r * 0.26 + lx * sa + ly * ca) for lx, ly in visor_local]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in vpts])
        pygame.draw.polygon(surf, dark, vpts)
        pygame.draw.line(surf, scale_col(col, 0.88), vpts[1], vpts[2], 2)
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.77))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.72))
        seam = pygame.Rect(int(px - r * 0.72), int(cy - r * 0.72), int(r * 1.44), int(r * 1.44))
        pygame.draw.arc(surf, dark, seam, 0.55, 2.60, 2)
        pygame.draw.circle(surf, lite, (int(px - r * 0.26), int(cy - r * 0.32)), max(2, int(r * 0.22)))
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy - r * 0.68)), max(3, int(r * 0.13)))
        pygame.draw.circle(surf, acc, (int(px), int(cy - r * 0.68)), max(2, int(r * 0.10)))

    elif item["id"] == "cap_blue":
        # Düz siperlikli "snapback": kırmızı şapkadan belirgin biçimde farklı,
        # köşeli bir taç ve geniş düz siperlik.
        cy = py - r * 0.60
        ax, ay = p.aim_dir
        ang = math.atan2(ay, ax)
        ca, sa = math.cos(ang), math.sin(ang)
        # düz, geniş ve köşeli siperlik — tacın ön alt kenarına yapışık
        visor_local = [(0.0, -r * 0.56), (r * 1.26, -r * 0.44), (r * 1.28, r * 0.44),
                       (0.0, r * 0.56)]
        vpts = [(px + lx * ca - ly * sa, cy + r * 0.40 + lx * sa + ly * ca) for lx, ly in visor_local]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in vpts])
        pygame.draw.polygon(surf, dark, vpts)
        pygame.draw.line(surf, lighten(col, 0.18), vpts[0], vpts[1], 2)
        crown = pygame.Rect(int(px - r * 0.62), int(cy - r * 0.64), int(r * 1.24), int(r * 1.10))
        pygame.draw.rect(surf, OUTLINE, crown.inflate(4, 4), border_radius=max(4, int(r * 0.34)))
        pygame.draw.rect(surf, col, crown, border_radius=max(4, int(r * 0.34)))
        pygame.draw.line(surf, dark, (int(px), crown.y + 4), (int(px), crown.bottom - 4), 2)
        pygame.draw.rect(surf, lite, (crown.x + 4, crown.y + 4, max(3, int(r * 0.40)), max(3, int(r * 0.28))),
                         border_radius=3)
        pygame.draw.circle(surf, acc, (int(px), int(crown.y + 1)), max(2, int(r * 0.10)))

    elif item["id"] == "wizard_hat":
        # Ucu hafif kıvrık külah + yıldızlı bant.
        by = py - r - 2
        tip_sway = math.sin(t * 1.6) * 3.0
        tip = (px + 4 + tip_sway, by - 32)
        mid = (px + 1, by - 14)
        left, right = (px - 15, by + 6), (px + 15, by + 6)
        pts = [left, right, tip, mid]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, dark, [mid, tip, (tip[0] - 4, tip[1] + 4)])
        pygame.draw.line(surf, lite, left, (tip[0] - 2, tip[1] + 3), 2)
        band = pygame.Rect(int(px - 16), int(by - 2), 32, max(4, int(r * 0.22)))
        pygame.draw.rect(surf, OUTLINE, band.inflate(2, 2), border_radius=3)
        pygame.draw.rect(surf, dark, band, border_radius=3)
        pygame.draw.ellipse(surf, OUTLINE, (int(px - 18), int(by + 1), 36, 10))
        pygame.draw.ellipse(surf, col, (int(px - 17), int(by + 2), 34, 8))
        pygame.draw.ellipse(surf, lite, (int(px - 15), int(by + 3), 30, 3))
        add_glow(surf, tip[0], tip[1] + 2, 12, acc, .55 + .18 * math.sin(t * 5))
        pygame.draw.circle(surf, acc, (int(tip[0]), int(tip[1] + 2)), 3)
        for i in range(3):
            sx = px - 10 + i * 10
            sy = by - 1 + (i % 2) * 3
            tw = 1 + max(0.0, math.sin(t * 4 + i * 2.1)) * 1.6
            pygame.draw.circle(surf, acc, (int(sx), int(sy)), int(tw))

    elif item["id"] == "crown_gold":
        # Beş uçlu taç: uçlarda taşlar, altta kalın bant.
        by = py - r - 3
        pts = [(px - 13, by + 9), (px - 13, by - 1), (px - 6, by + 6), (px, by - 9),
               (px + 6, by + 6), (px + 13, by - 1), (px + 13, by + 9)]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, acc, pts, 1)
        band = pygame.Rect(int(px - 14), int(by + 7), 28, max(4, int(r * 0.24)))
        pygame.draw.rect(surf, OUTLINE, band.inflate(2, 2), border_radius=2)
        pygame.draw.rect(surf, dark, band, border_radius=2)
        pygame.draw.line(surf, lite, (band.x + 2, band.y + 1), (band.right - 2, band.y + 1), 1)
        gems = ((px, by - 6, (230, 60, 90)), (px - 13, by - 1, (90, 190, 255)), (px + 13, by - 1, (120, 235, 150)))
        for gx, gy, gc in gems:
            pygame.draw.circle(surf, OUTLINE, (int(gx), int(gy)), 3)
            pygame.draw.circle(surf, gc, (int(gx), int(gy)), 2)
        add_glow(surf, px, by, 18, col, .40 + .18 * math.sin(t * 3.4))

    elif item["id"] == "halo_ring":
        # Çift halka + yumuşak nabız; hafifçe süzülür.
        bob = math.sin(t * 2.0) * 1.8
        hy = py - r - 16 + bob
        add_glow(surf, px, hy, 22, col, .5 + .14 * math.sin(t * 4))
        pygame.draw.ellipse(surf, scale_col(acc, 0.55), (int(px - 18), int(hy - 5), 36, 11), 3)
        pygame.draw.ellipse(surf, acc, (int(px - 16), int(hy - 4), 32, 9), 2)
        pygame.draw.ellipse(surf, lighten(acc, 0.5), (int(px - 12), int(hy - 3), 24, 4), 1)
        for i in range(3):
            a = t * 1.4 + i * math.tau / 3
            sx = px + math.cos(a) * 17
            sy = hy + math.sin(a) * 4.5
            pygame.draw.circle(surf, acc, (int(sx), int(sy)), 1 + int(max(0.0, math.sin(t * 5 + i)) * 1.5))

    elif item["id"] == "beanie_gray":
        # Örgü bere: dokulu gövde, katlı bant ve ponpon.
        cy = py - r * 0.64
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.74))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.69))
        for i in range(-2, 3):
            kx = px + i * r * 0.24
            pygame.draw.line(surf, dark, (int(kx), int(cy - r * 0.55)), (int(kx), int(cy + r * 0.34)), 1)
        pygame.draw.circle(surf, lite, (int(px - r * 0.26), int(cy - r * 0.30)), max(2, int(r * 0.20)))
        band = pygame.Rect(0, 0, int(r * 1.48), int(r * 0.34))
        band.center = (int(px), int(cy + r * 0.44))
        pygame.draw.ellipse(surf, OUTLINE, band.inflate(3, 3))
        pygame.draw.ellipse(surf, dark, band)
        pygame.draw.ellipse(surf, lighten(col, 0.18), (band.x + 2, band.y + 1, band.w - 4, max(2, band.h // 2)))
        pom = (int(px), int(cy - r * 0.78 + math.sin(t * 2.4) * 1.2))
        pygame.draw.circle(surf, OUTLINE, pom, max(4, int(r * 0.20)))
        pygame.draw.circle(surf, acc, pom, max(3, int(r * 0.17)))
        pygame.draw.circle(surf, lighten(acc, 0.4), (pom[0] - 1, pom[1] - 1), max(1, int(r * 0.07)))

    elif item["id"] == "viking_helm":
        # Miğfer + burun koruması + kıvrık boynuzlar + perçinler.
        cy = py - r * 0.60
        pygame.draw.circle(surf, OUTLINE, (int(px), int(cy)), int(r * 0.70))
        pygame.draw.circle(surf, col, (int(px), int(cy)), int(r * 0.64))
        pygame.draw.circle(surf, lite, (int(px - r * 0.24), int(cy - r * 0.28)), max(2, int(r * 0.18)))
        rim = pygame.Rect(0, 0, int(r * 1.32), int(r * 0.26))
        rim.center = (int(px), int(cy + r * 0.40))
        pygame.draw.ellipse(surf, OUTLINE, rim.inflate(3, 3))
        pygame.draw.ellipse(surf, dark, rim)
        pygame.draw.rect(surf, OUTLINE, (int(px - 4), int(cy - r * 0.08), 8, int(r * 0.72)))
        pygame.draw.rect(surf, dark, (int(px - 3), int(cy - r * 0.08), 6, int(r * 0.70)))
        for s in (-1, 1):
            pygame.draw.circle(surf, dark, (int(px + s * r * 0.40), int(cy + r * 0.20)), max(2, int(r * 0.08)))
            hx0 = px + s * r * 0.52
            hy0 = cy - r * 0.16
            pts = [(hx0, hy0 + 4),
                   (hx0 + s * 7, hy0 - 12),
                   (hx0 + s * 19, hy0 - 19),
                   (hx0 + s * 15, hy0 - 8),
                   (hx0 + s * 17, hy0 + 2),
                   (hx0 + s * 7, hy0 + 6)]
            pygame.draw.polygon(surf, OUTLINE, [(x_ + s, y_ + 1) for x_, y_ in pts])
            pygame.draw.polygon(surf, acc, pts)
            pygame.draw.polygon(surf, scale_col(acc, 0.7), pts, 1)
            pygame.draw.line(surf, scale_col(acc, 0.72), (hx0 + s * 8, hy0 - 10), (hx0 + s * 15, hy0 - 14), 1)

    elif item["id"] == "ninja_hood":
        # Kukuleta + göz açıklığı bandı + arkada uçuşan kuşak.
        cy = py - r * 0.55
        tail = math.sin(t * 2.6) * r * 0.18
        pts = [(px - r * 0.78, cy + r * 0.38), (px - r * 0.62, cy - r * 0.58),
               (px, cy - r * 0.90), (px + r * 0.62, cy - r * 0.58), (px + r * 0.78, cy + r * 0.38)]
        pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 2) for x_, y_ in pts])
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, lighten(col, 0.22),
                            [(px - r * 0.52, cy - r * 0.40), (px, cy - r * 0.82), (px + r * 0.06, cy - r * 0.46)])
        band = pygame.Rect(0, 0, int(r * 1.54), int(r * 0.30))
        band.center = (int(px), int(cy + r * 0.16))
        pygame.draw.ellipse(surf, OUTLINE, band.inflate(3, 3), 3)
        pygame.draw.ellipse(surf, acc, band, 2)
        kx, ky = px + r * 0.70, cy + r * 0.10
        pygame.draw.lines(surf, OUTLINE, False,
                          [(kx, ky), (kx + r * 0.30, ky + r * 0.22), (kx + r * 0.56, ky + r * 0.10 + tail)], 5)
        pygame.draw.lines(surf, acc, False,
                          [(kx, ky), (kx + r * 0.30, ky + r * 0.22), (kx + r * 0.56, ky + r * 0.10 + tail)], 2)

    elif item["id"] == "flower_crown":
        # Gerçek taç yapraklı çiçekler + aralarında küçük yeşil yapraklar.
        ring_y = py - r * 0.38
        rx, ry = r * 0.80, r * 0.38
        n = 6
        for i in range(n):
            ang = i * math.tau / n - math.pi / 2
            cxf = px + math.cos(ang) * rx
            cyf = ring_y + math.sin(ang) * ry
            if i % 2 == 1:
                lp = [(cxf, cyf + 3), (cxf + 5, cyf - 3), (cxf, cyf - 8), (cxf - 5, cyf - 3)]
                pygame.draw.polygon(surf, OUTLINE, [(x_, y_ + 1) for x_, y_ in lp])
                pygame.draw.polygon(surf, (110, 180, 110), lp)
                continue
