class ComboMeter:
    def __init__(self):
        self.count = 0
        self.best = 0
        self.timer = 0.0
        self.window = 2.1
        self.pulse = 0.0

    def add_kill(self):
        self.count += 1
        self.best = max(self.best, self.count)
        self.timer = self.window
        self.pulse = 1.0

    def multiplier(self):
        return 1.0 + min(self.count * 0.04, 2.0)

    def update(self, dt):
        if self.timer > 0:
            self.timer -= dt
            if self.timer <= 0:
                self.count = 0
        if self.pulse > 0:
            self.pulse = max(0.0, self.pulse - dt * 3)


