# =====================================================================
# YETENEK ÇUBUĞU
# ---------------------------------------------------------------------
# Ekranın altındaki yetenek yuvaları. Her yuva bir tuşu, bir simgeyi ve
# (varsa) canlı bekleme süresini gösterir.
#
# YENİ YETENEK EKLEMEK: aşağıdaki listeye bir sözlük eklemek yeterli.
#   key   : ekranda görünen tuş etiketi
#   name  : yuvanın altındaki kısa ad
#   icon  : draw_icon() simge adı
#   color : yuva rengi
#   cd    : (kalan, toplam) döndüren fonksiyon — bekleme süresi yoksa None
#   lock  : True dönerse yuva kilitli (gri) çizilir — henüz açılmamış yetenekler
# Çubuk genişliği yuva sayısına göre kendiliğinden ortalanır.
# =====================================================================

SKILL_SLOTS = [
    {"key": "SOL TIK", "pad": "fire", "name": "ATEŞ", "icon": "target", "color": (150, 210, 255),
     "cd": lambda p: (p.atk_timer, p.eff_atk_cd())},
    {"key": "SPACE", "pad": "bonk", "name": "BONK", "icon": "fist", "color": (245, 150, 80),
     "cd": lambda p: (p.bonk_timer, p.eff_bonk_cd())},
    {"key": "SHIFT", "pad": "dash", "name": "DASH", "icon": "dash", "color": (130, 225, 210),
     "cd": lambda p: (p.dash_cd_timer, p.eff_dash_cd())},
    {"key": "B", "pad": "shop", "name": "MARKET", "icon": "coin", "color": GOLD, "cd": None},
]

# Yalnızca belirli skinlerde görünen ek yuvalar.
SKILL_SLOT_SMASH = {"key": "SPACE", "pad": "bonk", "name": "EZİCİ", "icon": "skull", "color": (150, 255, 130),
                    "cd": lambda p: (p.smash_timer, RunState.TITAN_SMASH_CD)}


def skill_slots_for(p):
    """Oyuncunun skinine göre gösterilecek yetenek yuvaları."""
    slots = list(SKILL_SLOTS)
    if getattr(p, "titan_smash", 0):
        slots.insert(2, SKILL_SLOT_SMASH)
    # SKİN ÖZEL YETENEĞİ: her skinin kendi yuvası. Tuş etiketi yerine yeteneğin
    # TOPLAM bekleme süresi yazar (örn. "60sn"); yuvanın içindeki sayı ise
    # yeteneğin gelmesine kaç saniye kaldığını gösterir.
    ult = getattr(p, "ult", None)
    if ult:
        slots.append({"key": L("ui.sec_fmt", int(round(ult["cd"]))),
                      # Yeteneğin KISA adı (yuvanın altında) — her dilde ayrı,
                      # çünkü "BLOOD FRENZY"nin ilk kelimesi iyi bir etiket değil.
                      "name": LX("ults." + str(ult.get("id", "")),
                                 ult.get("short") or ult["name"].split()[0]),
                      "icon": ult.get("icon", "star"),
                      "color": tuple(ult.get("color", GOLD)),
                      "cd": lambda pp: (pp.ult_timer, pp.ult_cd)})
    # NOT: SİLAHLAR ARTIK BU ÇUBUKTA DEĞİL. Oyuncunun seçtiği 4 silah sol üstteki
    # SİLAH YUVALARI panelinde gösteriliyor (bkz. draw_weapon_slots); alt çubuk
    # yalnızca tuşla kullanılan yeteneklere ayrıldı.
    return slots


# Yetenek çubuğu boyut kademeleri — duraklatma menüsünden değiştirilir.
SKILL_SCALES = [(0.65, "ÇOK KÜÇÜK"), (0.75, "KÜÇÜK"), (0.85, "NORMAL"),
                (1.0, "BÜYÜK"), (1.15, "ÇOK BÜYÜK")]


def skill_scale_label():
    cur = float(CFG.get("skill_scale", 0.85))
    best = min(SKILL_SCALES, key=lambda it: abs(it[0] - cur))
    return LX("size." + best[1], best[1])


def cycle_skill_scale():
    """Bir sonraki boyut kademesine geçer ve seçilen değeri döndürür."""
    cur = float(CFG.get("skill_scale", 0.85))
    idx = min(range(len(SKILL_SCALES)), key=lambda i: abs(SKILL_SCALES[i][0] - cur))
    nxt = SKILL_SCALES[(idx + 1) % len(SKILL_SCALES)][0]
    CFG["skill_scale"] = nxt
    return nxt


_wslot_panel_cache = {}


def _fit_text(txt, size, max_w, bold=False):
    """Metni verilen genişliğe sığdırır; sığmıyorsa sonunu kısaltır."""
    if text_width(txt, size, bold) <= max_w:
        return txt
    for n in range(len(txt) - 1, 1, -1):
        cut = txt[:n] + "."
        if text_width(cut, size, bold) <= max_w:
            return cut
    return txt[:1]


def _slot_strip(w, h):
    """Yatay yuva şeridinin arka paneli (degrade + çerçeve) — önbellekli."""
    key = (w, h)
    bs = _wslot_panel_cache.get(key)
    if bs is not None:
        return bs
    if len(_wslot_panel_cache) > 24:
        _wslot_panel_cache.clear()
    bs = pygame.Surface((w, h), pygame.SRCALPHA)
    top_c, bot_c = (18, 20, 33, 176), (10, 11, 20, 196)
    for yy in range(h):
        f = yy / max(1, h - 1)
        pygame.draw.line(bs, tuple(int(lerp(top_c[k], bot_c[k], f)) for k in range(4)),
                         (0, yy), (w, yy))
    mask = pygame.Surface((w, h), pygame.SRCALPHA)
    pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(), border_radius=12)
    bs.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
    pygame.draw.rect(bs, (62, 70, 102, 200), bs.get_rect(), width=2, border_radius=12)
    pygame.draw.line(bs, (148, 158, 206, 110), (12, 1), (w - 12, 1), 1)
    _wslot_panel_cache[key] = bs
    return bs


def _empty_slot(surf, r, t, i, radius=10):
    """BOŞ YUVA: nefes alan kesik çizgili çerçeve + soluk artı."""
    breathe = 0.5 + 0.5 * math.sin(t * 1.6 + i * 0.7)
    pygame.draw.rect(surf, (15, 16, 25), r, border_radius=radius)
    dash_col = tuple(int(lerp(40, 68, breathe)) for _ in range(3))
    dr = r.inflate(-3, -3)
    seg, gapl = 6, 5
    pts = [dr.topleft, dr.topright, dr.bottomright, dr.bottomleft, dr.topleft]
    edges = list(zip(pts, pts[1:]))
    perim = 2 * (dr.w + dr.h)
    pos = 0.0
    while pos < perim:
        d = pos
        for (ax, ay), (bx, by) in edges:
            elen = math.hypot(bx - ax, by - ay)
            if d <= elen:
                f0, f1 = d / elen, min(1.0, (d + seg) / elen)
                pygame.draw.line(surf, dash_col,
                                 (ax + (bx - ax) * f0, ay + (by - ay) * f0),
                                 (ax + (bx - ax) * f1, ay + (by - ay) * f1), 2)
                break
            d -= elen
        pos += seg + gapl
    a_ = int(55 + 65 * breathe)
    ps = pygame.Surface(r.size, pygame.SRCALPHA)
    arm = max(4, r.w * 0.13)
    pygame.draw.line(ps, (140, 150, 190, a_), (r.w / 2 - arm, r.h / 2), (r.w / 2 + arm, r.h / 2), 2)
    pygame.draw.line(ps, (140, 150, 190, a_), (r.w / 2, r.h / 2 - arm), (r.w / 2, r.h / 2 + arm), 2)
    surf.blit(ps, r.topleft)


def _level_badge(surf, cx, cy, lvl, col, maxed=False, h=18):
    """Yuvanın köşesindeki seviye madalyonu (iki haneli sayıda hap biçimi)."""
    txt = str(lvl)
    bw = h + (0 if lvl < 10 else 7)
    badge = pygame.Rect(0, 0, bw, h)
    badge.center = (int(cx), int(cy))
    pygame.draw.rect(surf, (9, 10, 17), badge, border_radius=h // 2)
    pygame.draw.rect(surf, GOLD if maxed else col, badge, width=2, border_radius=h // 2)
    draw_text(surf, txt, badge.center, 10 if lvl < 10 else 9,
              GOLD if maxed else lighten(col, 0.2), bold=True, center=True, shadow=False)


# Yatay şeritlerin ortak ölçüleri. Hepsi tek yerde dursun ki silah ve kitap
# şeritleri birbiriyle HİZALI kalsın (eskiden yuvalar sol kenarda dikey bir
# sütundu ve canın altındaki alanı boydan boya kapatıyordu).
HUD_STRIP_X = 18
WSLOT_CELL = 48
WSLOT_GAP = 8
BSLOT_CELL = 38
BSLOT_GAP = 7
HUD_WEAPON_Y = 96        # silah şeridinin üst kenarı
HUD_BOOK_Y = HUD_WEAPON_Y + WSLOT_CELL + 35   # kitap şeridinin üst kenarı


def draw_weapon_slots(surf, run, t):
    """CANIN ALTINDAKİ YATAY SİLAH ŞERİDİ.

    v3.16: yuvalar artık sol kenarda dikey bir sütun değil, can/tecrübe
    çubuklarının hemen ALTINDA YATAY bir şerit. Böylece hem sahanın solu
    açılıyor hem de hemen altındaki KİTAP şeridiyle birlikte "takımın" tek
    bakışta okunuyor: üstte 4 silah, altta 4 kitap + 1 nadir.
    """
    p = run.player
    cell, gap = WSLOT_CELL, WSLOT_GAP
    keys = [k for k in BOSS_WEAPONS_ORDER if p.weapons.get(k, 0) > 0]
    n_filled = len(keys)
    n = max(MAX_RUN_WEAPONS, n_filled)
    x0, y0 = HUD_STRIP_X, HUD_WEAPON_Y

    back = pygame.Rect(x0 - 8, y0 - 17, n * cell + (n - 1) * gap + 16, cell + 25)
    surf.blit(_slot_strip(back.w, back.h), back.topleft)
    full = n_filled >= MAX_RUN_WEAPONS
    hcol = GOLD if full else TEXT_DIM
    draw_text(surf, L("ui.weapons"), (back.x + 10, y0 - 15), 10, hcol, bold=True, shadow=False)
    draw_text(surf, f"{n_filled}/{MAX_RUN_WEAPONS}",
              (back.x + 14 + text_width(L("ui.weapons"), 10, True), y0 - 15), 10,
              hcol if full else (104, 110, 136), bold=True, shadow=False)

    for i in range(n):
        r = pygame.Rect(x0 + i * (cell + gap), y0, cell, cell)
        if i >= n_filled:
            _empty_slot(surf, r, t, i)
            continue

        key = keys[i]
        w = WEAPON_BY_KEY[key]
        lvl = p.weapons[key]
        col = tuple(w["color"])
        passive = bool(w.get("passive"))
        timed = bool(w.get("timed"))
        invis_now = timed and getattr(p, "invis_t", 0.0) > 0
        if timed:
            remain, total_cd = ((0.0, 0.0) if invis_now
                                else (max(0.0, getattr(p, "cloak_timer", 0.0)),
                                      cloak_cooldown(lvl)))
        elif passive:
            remain, total_cd = 0.0, 0.0
        else:
            remain = max(0.0, p.weapon_timers.get(key, 0.0))
            total_cd = weapon_cooldown(w, lvl)
        ready = (passive and not timed) or invis_now or remain <= 0.001 or total_cd <= 0
        frac = 0.0 if ready else clamp(remain / max(0.0001, total_cd), 0.0, 1.0)
        pulse = 0.5 + 0.5 * math.sin(t * 3.2 + i * 0.9)

        if ready:
            add_glow(surf, r.centerx, r.centery, cell * 0.95, col, 0.20 + 0.13 * pulse)
        pygame.draw.rect(surf, (17, 18, 29), r, border_radius=10)
        surf.blit(_slot_tint(r.size, scale_col(col, 0.55), 46), r.topleft)

        if frac > 0:
            fh = max(1, int(r.h * frac))
            surf.blit(_slot_cool(r.w, fh, lighten(col, 0.3)), (r.x, r.y + r.h - fh))
        else:
            surf.blit(_slot_tint(r.size, col, int(150 * (0.14 + 0.10 * pulse))),
                      r.topleft)

        edge_col = col if ready else scale_col(col, 0.42)
        pygame.draw.rect(surf, edge_col, r, width=3 if (ready and pulse > 0.55) else 2,
                         border_radius=10)

        icx, icy = r.centerx, r.centery - 1
        icon_r = cell * 0.30
        for k_ in range(8):
            a = t * 0.6 + k_ * math.tau / 8
            r0, r1 = icon_r * 1.26, icon_r * (1.40 + 0.06 * pulse)
            ring_col = edge_col if ready else scale_col(edge_col, 0.7)
            pygame.draw.line(surf, ring_col,
                             (icx + math.cos(a) * r0, icy + math.sin(a) * r0),
                             (icx + math.cos(a) * r1, icy + math.sin(a) * r1), 1)
        pygame.draw.circle(surf, (12, 13, 20), (int(icx), int(icy)), int(icon_r * 1.2))
        blit_sigil(surf, icx, icy, icon_r, key,
                   col if ready else scale_col(col, 0.55))

        if frac > 0:
            txt = f"{remain:.1f}"
            plaque = pygame.Rect(0, 0, text_width(txt, 12, True) + 8, 14)
            plaque.center = (r.centerx, r.centery - 2)
            ps = pygame.Surface(plaque.size, pygame.SRCALPHA)
            pygame.draw.rect(ps, (5, 5, 10, 175), ps.get_rect(), border_radius=5)
            surf.blit(ps, plaque.topleft)
            draw_text(surf, txt, (r.centerx, r.centery - 4), 12, WHITE, bold=True, center=True)

        # Rozet ÜST SAĞ köşede: alttaki ad yazısının üstüne binmesin.
        _level_badge(surf, r.right - 1, r.y + 1, lvl, col,
                     maxed=lvl >= weapon_max_level(w), h=17)
        # yuvanın ALTINDA kısa ad; sığmazsa kısaltılır
        name = _fit_text(w_name(w), 8, cell + gap - 1, bold=True)
        ncol = (CLOAK_COLOR2 if invis_now else
                (lighten(col, 0.25) if ready else (118, 124, 148)))
        draw_text(surf, name, (r.centerx, r.bottom + 3), 8, ncol, bold=True,
                  center=True, shadow=False)


# Yuvanın yarı saydam katmanları her karede YENİDEN AYRILIYORDU: 8 silah
# için kare başına 16 yüzey ayırma + doldurma. İkisi de yalnızca boyuta,
# renge ve saydamlığa bağlı, o yüzden saklanıyorlar.
_slot_layer_cache = {}


def _slot_tint(size, col, alpha):
    alpha = int(clamp(alpha, 0, 255)) // 6 * 6
    ck = ("t", size, (int(col[0]), int(col[1]), int(col[2])), alpha)
    sfc = _slot_layer_cache.get(ck)
    if sfc is None:
        if len(_slot_layer_cache) > 600:
            _slot_layer_cache.clear()
        sfc = pygame.Surface(size, pygame.SRCALPHA)
        pygame.draw.rect(sfc, (int(col[0]), int(col[1]), int(col[2]), alpha),
                         sfc.get_rect(), border_radius=10)
        _slot_layer_cache[ck] = sfc
    return sfc


def _slot_cool(w, h, line_col):
    ck = ("c", w, h, (int(line_col[0]), int(line_col[1]), int(line_col[2])))
    sfc = _slot_layer_cache.get(ck)
    if sfc is None:
        if len(_slot_layer_cache) > 600:
            _slot_layer_cache.clear()
        sfc = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(sfc, (6, 7, 14, 205), sfc.get_rect())
        pygame.draw.line(sfc, (int(line_col[0]), int(line_col[1]), int(line_col[2]), 150),
                         (2, 0), (w - 2, 0), 2)
        _slot_layer_cache[ck] = sfc
    return sfc


def draw_book_slots(surf, run, t):
    """SİLAH ŞERİDİNİN ALTINDAKİ YATAY KİTAP ŞERİDİ.

    v3.16: kitaplar da artık bir TAKIM. Dört normal yuva (her biri
    Lv.15'e kadar) ve en sağda altın çerçeveli TEK nadir yuva. Oyuncu
    seviye atlarken "silah mı, kitap mı?" sorusunu bu şeride bakarak
    cevaplıyor — eskiden kitapların oyunda hiçbir görünür izi yoktu ve
    oyun tamamen silah üzerine gidiyordu.
    """
    p = run.player
    cell, gap = BSLOT_CELL, BSLOT_GAP
    normals = [k for k in p.books if not BOOK_BY_KEY.get(k, {}).get("rare")]
    rares = [k for k in p.books if BOOK_BY_KEY.get(k, {}).get("rare")]
    n_norm = max(MAX_RUN_BOOKS, len(normals))
    n_rare = max(MAX_RUN_RARE_BOOKS, len(rares))
    n_tot = n_norm + n_rare
    x0, y0 = HUD_STRIP_X, HUD_BOOK_Y
    # Nadir yuva, normallerden biraz ayrı dursun: aradaki boşluk iki katı.
    sep = gap * 2

    width = n_tot * cell + (n_tot - 1) * gap + sep
    back = pygame.Rect(x0 - 8, y0 - 17, width + 16, cell + 22)
    surf.blit(_slot_strip(back.w, back.h), back.topleft)
    full_b = len(normals) >= MAX_RUN_BOOKS
    hcol = GOLD if full_b else TEXT_DIM
    draw_text(surf, L("ui.books_hud"), (back.x + 10, y0 - 15), 10, hcol, bold=True, shadow=False)
    draw_text(surf, f"{len(normals)}/{MAX_RUN_BOOKS}",
              (back.x + 14 + text_width(L("ui.books_hud"), 10, True), y0 - 15), 10,
              hcol if full_b else (104, 110, 136), bold=True, shadow=False)

    def slot_rect(i):
        x = x0 + i * (cell + gap) + (sep if i >= n_norm else 0)
        return pygame.Rect(x, y0, cell, cell)

    for i in range(n_tot):
        r = slot_rect(i)
        rare_slot = i >= n_norm
        idx = i - n_norm if rare_slot else i
        src = rares if rare_slot else normals
        if idx >= len(src):
            _empty_slot(surf, r, t, i + 3, radius=8)
            if rare_slot:
                # boş nadir yuva altın bir ipucu halkası taşır
                pygame.draw.rect(surf, scale_col(GOLD, 0.45), r, width=1, border_radius=8)
            continue

        key = src[idx]
        bk = BOOK_BY_KEY[key]
        lvl = p.books[key]
        col = tuple(bk["color"])
        maxed = lvl >= book_max_level(bk)
        pulse = 0.5 + 0.5 * math.sin(t * 2.4 + i * 0.8)

        add_glow(surf, r.centerx, r.centery, cell * 0.9, col, 0.16 + 0.10 * pulse)
        pygame.draw.rect(surf, (16, 17, 27), r, border_radius=8)
        tint = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.rect(tint, (*scale_col(col, 0.55), 44), tint.get_rect(), border_radius=8)
        surf.blit(tint, r.topleft)
        pygame.draw.rect(surf, GOLD if rare_slot else col, r,
                         width=3 if rare_slot else 2, border_radius=8)
        draw_icon(surf, r.centerx, r.centery - 1, bk.get("icon", "star"), col, cell * 0.26)
        _level_badge(surf, r.right - 1, r.y + 1, lvl, col, maxed=maxed, h=15)
        name = _fit_text(bk_short(bk), 8, cell + gap - 1, bold=True)
        draw_text(surf, name, (r.centerx, r.bottom + 3), 8, lighten(col, 0.2),
                  bold=True, center=True, shadow=False)


def draw_skill_bar(surf, run, t):
    """Ekranın alt ortasında yetenek yuvalarını çizer.

    Yuva boyutu CFG["skill_scale"] ile ölçeklenir; oyuncu duraklatma
    menüsünden küçültüp büyütebilir.
    """
    p = run.player
    slots = skill_slots_for(p)
    n = len(slots)
    k = clamp(float(CFG.get("skill_scale", 0.85)), 0.5, 1.4)
    sw, sh, gap = int(62 * k), int(62 * k), max(5, int(10 * k))
    total = n * sw + (n - 1) * gap
    x0 = VIRTUAL_W / 2 - total / 2
    y0 = VIRTUAL_H - sh - int(30 * k)

    # arka panel
    back = pygame.Rect(int(x0 - 12 * k), int(y0 - 10 * k), int(total + 24 * k), int(sh + 32 * k))
    bs = pygame.Surface(back.size, pygame.SRCALPHA)
    pygame.draw.rect(bs, (10, 11, 20, 188), bs.get_rect(), border_radius=14)
    pygame.draw.rect(bs, (58, 62, 88, 220), bs.get_rect(), width=2, border_radius=14)
    surf.blit(bs, back.topleft)

    for i, sk in enumerate(slots):
        r = pygame.Rect(int(x0 + i * (sw + gap)), int(y0), sw, sh)
        locked = bool(sk.get("lock") and sk["lock"](p))
        col = (86, 90, 112) if locked else sk["color"]

        remain, total_cd = 0.0, 0.0
        if sk.get("cd") and not locked:
            try:
                remain, total_cd = sk["cd"](p)
            except Exception:
                remain, total_cd = 0.0, 0.0
        ready = remain <= 0.001 or total_cd <= 0
        frac = 0.0 if ready else clamp(remain / max(0.0001, total_cd), 0.0, 1.0)

        # yuva zemini
        pygame.draw.rect(surf, (18, 19, 30), r, border_radius=10)
        # bekleme süresi: aşağıdan yukarı dolan karartma
        if frac > 0:
            fill_h = int(r.h * frac)
            cs = pygame.Surface((r.w, fill_h), pygame.SRCALPHA)
            pygame.draw.rect(cs, (6, 7, 14, 200), cs.get_rect())
            surf.blit(cs, (r.x, r.y + r.h - fill_h))
        elif not locked:
            # hazır: hafif nabız
            pulse = 0.18 + 0.10 * math.sin(t * 4 + i)
            gs = pygame.Surface((r.w, r.h), pygame.SRCALPHA)
            pygame.draw.rect(gs, (*col, int(255 * pulse)), gs.get_rect(), border_radius=10)
            surf.blit(gs, r.topleft)

        pygame.draw.rect(surf, col if (ready and not locked) else (52, 56, 76), r,
                         width=2, border_radius=10)

        # simge
        icon_col = col if (ready and not locked) else scale_col(col, 0.55)
        draw_icon(surf, r.centerx, r.centery - 4 * k, sk["icon"], icon_col, max(7, int(15 * k)))

        # kalan süre yazısı
        if frac > 0:
            draw_text(surf, f"{remain:.1f}", (r.centerx, r.centery - 8 * k), max(9, int(15 * k)), WHITE,
                      bold=True, center=True)

        # tuş etiketi
        kb = pygame.Rect(r.x + 3, int(r.bottom - 17 * k), r.w - 6, max(9, int(14 * k)))
        pygame.draw.rect(surf, (30, 33, 50) if not locked else (26, 27, 38), kb, border_radius=4)
        # KONTROLCÜ etkinse tuş yerine PAD DÜĞMESİ yazar: oyuncu elindeki
        # alete bakıp "SPACE" görmesin.
        klabel = PAD_LABELS.get(sk.get("pad", ""), "") if PAD_ACTIVE[0] else ""
        draw_text(surf, klabel or LX("key." + str(sk["key"]), sk["key"]), kb.center,
                  max(6, int(9 * k)), TEXT if not locked else (110, 114, 136),
                  bold=True, center=True, shadow=False)

        # yuva adı
        draw_text(surf, LX("slot." + str(sk.get("name", "")), sk.get("name", "")),
                  (r.centerx, r.bottom + 4 * k), max(7, int(10 * k)),
                  TEXT_DIM if not locked else (92, 96, 118), center=True, shadow=False)

        if locked:
            pygame.draw.line(surf, (140, 100, 110), (r.x + 8, r.y + 8), (r.right - 8, r.bottom - 8), 2)


# =====================================================================
# İSTATİSTİK PANELİ  (TAB / sağ üstteki "⋮" düğmesi)
# ---------------------------------------------------------------------
# v3.16 — YENİDEN TASARLANDI. Eskiden her satırın arkasında bir dolgu
# çubuğu olan tek parça uzun bir listeydi: ekranın neredeyse yarısını
# kaplıyor, oyun sırasında açıldığında sahayı kapatıyor ve hiçbir şey
# okunmuyordu. Artık klasik bir RPG künyesi gibi:
#
#   * KONU BAŞLIKLARINA ayrılmış  (HAYATTA KALMA / HASAR / HAREKET / KAZANÇ)
#   * çubuk yok — solda etiket, sağda değer, iki sütun hizalı
#   * yalnızca ANLAMLI satırlar görünür (kalkanın yoksa "Kalkan" satırı yok)
#   * panel belirgin biçimde daraldı ve kısaldı
#
# Ölçü birimi değişmedi: oran veren değerlerde "taban oyuncu = %100",
# yani hasarın iki katına çıkmışsa 2,0x yazar.
#
# YENİ SATIR EKLEMEK: player_stat_groups() içinde ilgili grubun listesine
# bir demet eklemek yeterli — (etiket, değer metni, renk).
# =====================================================================

STATS_BTN_W, STATS_BTN_H = 30, 26
STATS_PANEL_W = 254      # eski: 336 — panel daraldı
STATS_HEAD_H = 30        # başlık şeridinin yüksekliği
STATS_ROW_H = 17         # tek satırın yüksekliği
STATS_GROUP_GAP = 11     # gruplar arası boşluk
STATS_GROUP_HEAD_H = 13  # grup başlığının kapladığı yükseklik
_stats_head_cache = {}


def stats_button_rect():
    """Sağ üst köşedeki üç nokta düğmesi."""
    return pygame.Rect(VIRTUAL_W - STATS_BTN_W - 10, 8, STATS_BTN_W, STATS_BTN_H)


def _stats_header(w, h):
    """İstatistik panelinin başlık şeridi (degrade + alt ayraç) — önbellekli."""
    key = (w, h)
    sh = _stats_head_cache.get(key)
    if sh is None:
        if len(_stats_head_cache) > 6:
            _stats_head_cache.clear()
        sh = pygame.Surface((w, h), pygame.SRCALPHA)
        for yy in range(h):
            f = yy / max(1, h - 1)
            pygame.draw.line(sh, (int(lerp(34, 22, f)), int(lerp(52, 34, f)),
                                  int(lerp(44, 30, f)), 255), (0, yy), (w, yy))
        mask = pygame.Surface((w, h), pygame.SRCALPHA)
        pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(),
                         border_top_left_radius=10, border_top_right_radius=10,
                         border_bottom_left_radius=0, border_bottom_right_radius=0)
        sh.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
        _stats_head_cache[key] = sh
    return sh


def stats_panel_rect(n_rows, n_groups=0):
    """Panelin dikdörtgeni. Yükseklik, çizim düzeniyle BİREBİR aynı hesaplanır:
    başlık şeridi + her grubun kendi başlığı + satırlar + gruplar arası
    boşluk (ilk grup hariç) + alt pay."""
    b = stats_button_rect()
    h = (STATS_HEAD_H + n_rows * STATS_ROW_H
         + n_groups * STATS_GROUP_HEAD_H
         + max(0, n_groups - 1) * STATS_GROUP_GAP + 10)
    return pygame.Rect(VIRTUAL_W - STATS_PANEL_W - 10, b.bottom + 6, STATS_PANEL_W, h)


def _pct(v):
    """Oranı yüzdeye çevirir. Yüzde işaretinin yeri dile göre değişir:
    Türkçede "%100", İngilizcede "100%"."""
    return fmt_pct(v * 100)


def _mult(v):
    """Çarpanı okunur biçimde yazar: 2.0 -> "2,0x" (TR) / "2.0x" (EN).

    Ondalık ayracı da dile bağlı; Türkçede virgül, diğerlerinde nokta.
    """
    t = f"{v:.1f}x"
    return t.replace(".", ",") if lang() == "tr" else t


def _vamp_text(p):
    """Can çalma satırının yazısı.

    Tavan gizli kalırsa oyuncu "%30 can çalma" görüp hasarını büyütmeye
    çalışır, ama saniye tavanı yüzünden hiçbir şey kazanmaz. Bu yüzden
    saniye tavanı da yazılır."""
    oran = _pct(0.02 * p.vamp_level)
    if p.vamp_level <= 0:
        return oran
    return "%s (%s)" % (oran, L("st.vamp_cap", _pct(0.04 + 0.02 * p.vamp_level)))


def player_stat_groups(p, run):
    """İstatistikleri GRUPLANMIŞ biçimde döndürür.

    Dönüş: [(grup_adı, [(etiket, değer, renk), ...]), ...]

    v3.16: panel eskiden tek bir uzun liste + her satırda bir arkaplan
    çubuğuydu; ekranın yarısını kaplıyor ve okunmuyordu. Artık konu
    başlıklarına ayrılmış, çubuksuz, iki sütun hizalı bir künye: solda
    etiket, sağda değer. Panel bu sayede hem daha dar hem daha kısa.
    """
    dmg_r = p.eff_dmg() / max(1e-6, BASE_DMG)
    aspd_r = BASE_ATK_CD / max(1e-6, p.eff_atk_cd())
    spd_r = p.eff_speed() / max(1e-6, BASE_SPEED)
    pick_r = p.eff_pickup() / max(1e-6, BASE_PICKUP)
    dash_r = BASE_DASH_CD / max(1e-6, p.eff_dash_cd())
    bonk_r = BASE_BONK_CD / max(1e-6, p.eff_bonk_cd())
    base_dps = BASE_DMG * (1.0 + 0.05 * (1.6 - 1.0)) / BASE_ATK_CD

    hayat = [
        (L("st.max_hp"), f"{int(p.max_hp)}", (235, 120, 150)),
        (L("st.regen"), f"{p.eff_regen():.1f}" + L("ui.per_sec"), GREEN),
        (L("st.armor"), _pct(p.eff_armor()), (160, 180, 220)),
        (L("st.vamp"), _vamp_text(p), (220, 60, 90)),
    ]
    if p.shield_charges:
        hayat.append((L("st.shield"), f"{p.shield_charges}", (160, 170, 200)))
    if p.second_wind_charges:
        hayat.append((L("st.second"), f"{p.second_wind_charges}", GOLD))
    if p.thorns_level:
        hayat.append((L("st.thorns"), f"{p.thorns_level}", (170, 125, 90)))

    hasar = [
        (L("st.dmg"), _mult(dmg_r), (245, 120, 110)),
        (L("st.crit"), _pct(p.eff_crit_chance()), (230, 220, 120)),
        (L("st.critd"), _mult(p.eff_crit_dmg()), (255, 210, 130)),
        (L("st.aspd"), _pct(aspd_r), (150, 210, 255)),
        (L("st.dps"), _pct(p.estimated_dps() / max(1e-6, base_dps)), (255, 190, 90)),
        (L("st.multi"), f"{1 + p.multishot_level}", PURPLE),
        (L("st.pierce"), f"{p.eff_pierce_hits()}", RED),
    ]
    if p.boss_hunter:
        hasar.append((L("st.bossdmg"), f"+{_pct(p.boss_hunter_bonus())}", (200, 90, 220)))
    if p.execute_threshold > 0:
        hasar.append((L("st.execute"), _pct(p.execute_threshold), GOLD))

    hareket = [
        (L("st.speed"), _pct(spd_r), (130, 230, 170)),
        (L("st.dash"), _pct(dash_r), (130, 225, 210)),
        (L("st.bonk"), _pct(bonk_r), (245, 150, 80)),
        (L("st.pickup"), f"{int(p.eff_pickup())}", (150, 220, 255)),
    ]

    kazanc = [
        (L("st.gold"), _pct(p.eff_coin_mult()), GOLD),
        (L("st.xp"), _pct(p.eff_xp_mult()), PURPLE),
    ]
    if p.frenzy_stacks:
        kazanc.append((L("st.frenzy"), f"x{p.frenzy_stacks}", (255, 200, 80)))
    if p.soul_stacks:
        kazanc.append((L("st.souls"), f"x{p.soul_stacks}", (200, 120, 255)))

    return [(L("st.g_life"), hayat), (L("st.g_dmg"), hasar),
            (L("st.g_move"), hareket), (L("st.g_gain"), kazanc)]


def draw_stats_panel(surf, run, t):
    """İstatistik panelini çizer ve kapladığı dikdörtgeni döndürür."""
    p = run.player
    groups = player_stat_groups(p, run)
    n_rows = sum(len(r) for _g, r in groups)
    rect = stats_panel_rect(n_rows, len(groups))
    panel(surf, rect, bg=(13, 14, 23), edge=(96, 106, 152), alpha=244, radius=11, edge_w=2)

    # ---- başlık şeridi: koyu yeşil bir künye bandı + iki yanında köşebent ----
    head = pygame.Rect(rect.x + 2, rect.y + 2, rect.w - 4, STATS_HEAD_H - 6)
    surf.blit(_stats_header(head.w, head.h), head.topleft)
    pygame.draw.line(surf, (150, 190, 160), (head.x + 6, head.bottom - 1),
                     (head.right - 6, head.bottom - 1), 1)
    draw_text(surf, L("ui.stats"), (head.x + 12, head.y + 5), 16, (226, 236, 226),
              bold=True, shadow=False)
    for sgn, ax in ((1, head.right - 11), (-1, head.x + 7)):
        pygame.draw.polygon(surf, (190, 214, 192),
                            [(ax, head.y + 5), (ax + sgn * 5, head.y + 5),
                             (ax + sgn * 5, head.y + 10), (ax, head.y + 10)], 1)

    y = rect.y + STATS_HEAD_H
    for gi, (gname, rows) in enumerate(groups):
        if gi:
            y += STATS_GROUP_GAP
            pygame.draw.line(surf, (36, 40, 58), (rect.x + 12, y - 6),
                             (rect.right - 12, y - 6), 1)
        draw_text(surf, gname, (rect.x + 13, y - 1), 9, (122, 132, 166),
                  bold=True, shadow=False)
        y += STATS_GROUP_HEAD_H
        for (label, value, col) in rows:
            draw_text(surf, label, (rect.x + 15, y), 13, (206, 211, 228), shadow=False)
            draw_text(surf, value, (rect.right - 15, y), 13, col, bold=True,
                      right=True, shadow=False)
            y += STATS_ROW_H
    return rect


def draw_stats_button(surf, run, mouse_pos, t):
    """Sağ üstteki üç nokta düğmesi (açıkken altın renginde yanar)."""
    r = stats_button_rect()
    open_ = getattr(run, "show_stats", False)
    hover = r.collidepoint(mouse_pos) if mouse_pos else False
    bg = (58, 50, 26) if open_ else ((40, 44, 64) if hover else (24, 26, 42))
    pygame.draw.rect(surf, bg, r, border_radius=7)
    pygame.draw.rect(surf, GOLD if (open_ or hover) else PANEL_EDGE, r, width=2, border_radius=7)
    dot = GOLD if (open_ or hover) else (170, 178, 205)
    for i in (-1, 0, 1):
        pygame.draw.circle(surf, dot, (r.centerx, int(r.centery + i * 7)), 2)


_hud_bar_cache = {}


def _hud_scrim(w, h):
    """Üstteki yazıların arkasına basılan ÇOK HAFİF karartma.

    v3.16: eskiden burada tam genişlikte, opak lacivert bir dikdörtgen vardı
    ve sahanın üst şeridini bütünüyle kapatıyordu ("yukarıyı da görelim").
    Dikdörtgen kaldırıldı; yerine yalnızca yazıların okunması için aşağı
    doğru tamamen SÖNEN, çok soluk bir gölge kaldı. Arena artık yukarıya
    kadar görünüyor.
    """
    key = (w, h)
    sc = _hud_bar_cache.get(key)
    if sc is None:
        if len(_hud_bar_cache) > 8:
            _hud_bar_cache.clear()
        sc = pygame.Surface((w, h), pygame.SRCALPHA)
        for yy in range(h):
            f = yy / max(1, h - 1)
            a = int(lerp(104, 0, f ** 0.75))
            if a <= 0:
                continue
            pygame.draw.line(sc, (6, 7, 14, a), (0, yy), (w, yy))
        _hud_bar_cache[key] = sc
    return sc


def draw_hud(surf, run, t):
    p = run.player
    # v3.16: üstteki OPAK LACİVERT ŞERİT KALDIRILDI. Yerinde yalnızca
    # yazıların okunabilmesi için aşağı doğru sönen çok soluk bir gölge var;
    # arena artık ekranın en üstüne kadar görünüyor.
    surf.blit(_hud_scrim(VIRTUAL_W, ARENA_MARGIN_TOP + 14), (0, 0))

    hp_rect = pygame.Rect(18, 14, 248, 20)
    frac = clamp(p.hp / p.max_hp, 0, 1)
    hp_col = GREEN if frac > 0.5 else (ORANGE if frac > 0.25 else RED)
    # can azalınca çubuk nabız gibi atsın
    if frac < 0.35:
        add_glow(surf, hp_rect.centerx, hp_rect.centery, 130, RED,
                 0.10 + 0.10 * (0.5 + 0.5 * math.sin(t * 6)))
    draw_bar(surf, hp_rect, frac, hp_col)
    # çubuğun üst yarısına cam parlaması
    gl = pygame.Surface((hp_rect.w - 4, hp_rect.h // 2 - 1), pygame.SRCALPHA)
    gl.fill((255, 255, 255, 26))
    surf.blit(gl, (hp_rect.x + 2, hp_rect.y + 2))
    draw_text(surf, f"{int(p.hp)}/{int(p.max_hp)}", hp_rect.center, 14, WHITE, bold=True, center=True)
    draw_icon(surf, hp_rect.x - 12, hp_rect.centery, "heart", RED, 12)

    xp_rect = pygame.Rect(18, 40, 248, 10)
    draw_bar(surf, xp_rect, p.xp / p.xp_to_next, PURPLE, radius=5)
    # seviye rozeti: sayı düz yazı yerine mor bir madalyonda
    lv_txt = f"LV {p.level}"
    lv_r = pygame.Rect(0, 0, text_width(lv_txt, 14, True) + 18, 19)
    lv_r.midleft = (xp_rect.right + 8, xp_rect.centery)
    pygame.draw.rect(surf, (28, 20, 44), lv_r, border_radius=9)
    pygame.draw.rect(surf, PURPLE, lv_r, width=1, border_radius=9)
    draw_text(surf, lv_txt, lv_r.center, 14, PURPLE, bold=True, center=True, shadow=False)

    draw_coin_label(surf, 18 + coin_label_width(fmt_num(run.gold_wallet), 15, 7) / 2,
                    62, fmt_num(run.gold_wallet), GOLD, 15, icon_r=7)

    # --- PATRON DURUM ETKİLERİ: altının sağında küçük sayaçlar ---
    st_x = 136
    for (act, icon, scol, label) in ((p.burn_t, "flame", (255, 150, 70), "YANIK"),
                                     (p.poison_t, "drop", (150, 240, 120), "ZEHİR"),
                                     (p.slow_t, "snow", (150, 210, 255), "YAVAŞ")):
        if act <= 0:
            continue
        chip = pygame.Rect(st_x, 54, 74, 18)
        cs = pygame.Surface(chip.size, pygame.SRCALPHA)
        pygame.draw.rect(cs, (*scol, 52), cs.get_rect(), border_radius=6)
        pygame.draw.rect(cs, (*scol, 190), cs.get_rect(), width=1, border_radius=6)
        surf.blit(cs, chip.topleft)
        draw_icon(surf, chip.x + 11, chip.centery, icon, scol, 6)
        draw_text(surf, f"{label} {act:0.1f}", (chip.x + 20, chip.y + 3), 10, scol,
                  bold=True, shadow=False)
        st_x += 80

    draw_text(surf, fmt_time(run.run_time), (VIRTUAL_W / 2, 18), 26, TEXT, bold=True, center=True)

    w = run.waves
    if run.bosses:
        n = len([b for b in run.bosses if b.alive])
        label = "PATRON DALGASI" if n <= 1 else f"PATRON DALGASI  ×{n}"
        draw_text(surf, label, (VIRTUAL_W / 2, 41), 15, RED, bold=True, center=True)
        draw_text(surf, L("ui.boss_hint"),
                  (VIRTUAL_W / 2, 61), 11, TEXT_DIM, center=True, shadow=False)
    else:
        # Dalga artık süreyle değil SKORLA ilerliyor; oyuncu hedefe ne kadar
        # kaldığını buradan görür. Yoğunluk penceresi açıkken şerit turuncuya döner.
        surge = w.surge_active()
        next_is_boss = w.is_boss_wave(w.wave + 1)
        hellish = run.biome == "hell"
        wave_col = ORANGE if surge else (GOLD if next_is_boss else
                                         ((255, 130, 80) if hellish else CYAN))
        head = L("ui.hell_wave", w.wave) if hellish else L("ui.wave", w.wave)
        if run.hell_portal is not None and not hellish:
            head += "   » CEHENNEM KAPISI AÇIK (E)"
        if next_is_boss:
            head += "   » SONRAKİ: PATRON"
        draw_text(surf, head, (VIRTUAL_W / 2, 40), 14, wave_col, bold=True, center=True)

        gbar = pygame.Rect(VIRTUAL_W / 2 - 120, 52, 240, 7)
        draw_bar(surf, gbar, w.goal_progress(), wave_col,
                 bg=(16, 17, 26), border=(52, 56, 76), radius=4)
        draw_text(surf, f"{fmt_num(min(w.wave_score, w.wave_goal))} / {fmt_num(w.wave_goal)}",
                  (VIRTUAL_W / 2, 64), 10, TEXT_DIM, center=True, shadow=False)

        if surge:
            draw_text(surf, L("ui.surge", f"{w.surge_timer:0.1f}"), (gbar.right + 10, 49), 12,
                      ORANGE, bold=True, shadow=False)

    # Sağ üstteki "⋮" istatistik düğmesine yer açmak için biraz sola kaydırıldı.
    rx = VIRTUAL_W - 48
    draw_text(surf, L("ui.score", fmt_num(run.score)), (rx, 14), 18, TEXT, bold=True, right=True)
    draw_text(surf, L("ui.kills", run.kills), (rx, 38), 14, TEXT_DIM, right=True)

    icon_x = rx
    badges = []
    if p.fire_level: badges.append(("bolt", ORANGE, p.fire_level))
    if p.ice_level: badges.append(("target", CYAN, p.ice_level))
    if p.shield_charges: badges.append(("shield", (160, 170, 200), p.shield_charges))
    if p.pierce_bonus: badges.append(("sword", RED, p.pierce_bonus))
    if p.multishot_level: badges.append(("star", PURPLE, p.multishot_level))
    if p.explosive_level: badges.append(("star", (240, 110, 60), p.explosive_level))
    if p.vamp_level: badges.append(("heart", (220, 60, 90), p.vamp_level))
    if p.thorns_level: badges.append(("shield", (170, 125, 90), p.thorns_level))
    if p.chain_level: badges.append(("bolt", (120, 200, 255), p.chain_level))
    if p.homing_level: badges.append(("target", (140, 220, 200), p.homing_level))
    if p.orbit_level: badges.append(("orbit", (150, 220, 255), p.orbit_level))
    if p.storm_level: badges.append(("bolt", (190, 215, 255), p.storm_level))
    if p.second_wind_charges: badges.append(("heart", GOLD, p.second_wind_charges))
    if p.holy_flame: badges.append(("cross", (255, 235, 150), p.holy_flame))
    if p.soul_harvest: badges.append(("skull", (200, 120, 255), p.soul_harvest))
    if p.angel_wing: badges.append(("boot", (220, 240, 255), p.angel_wing))
    if p.purgatory_level: badges.append(("shield", (255, 215, 120), p.purgatory_level))
    if p.execute_threshold > 0: badges.append(("sword", GOLD, round(p.execute_threshold * 100)))
    by = 62
    for kind, col, lvl in badges[:14]:
        icon_x -= 26
        draw_icon(surf, icon_x, by, kind, col, 11)
        draw_text(surf, f"x{lvl}", (icon_x + 12, by + 6), 11, col, shadow=False)

    if p.frenzy_stacks > 0:
        draw_text(surf, L("ui.frenzy", p.frenzy_stacks), (VIRTUAL_W / 2, 96), 14, (255, 200, 80), bold=True, center=True)

    if run.combo.count >= 3:
        pulse = 1 + run.combo.pulse * 0.4
        size = int(20 * pulse)
        col = GOLD if run.combo.count >= 20 else (ORANGE if run.combo.count >= 10 else CYAN)
        draw_text(surf, L("ui.combo", run.combo.count), (VIRTUAL_W / 2, 76), size, col, bold=True, center=True)
        br = pygame.Rect(VIRTUAL_W / 2 - 80, 94, 160, 5)
        draw_bar(surf, br, run.combo.timer / run.combo.window, col, radius=3)

    if run.waves.announce_timer > 0 and run.waves.announce_text:
        a = clamp(run.waves.announce_timer / 2.2, 0, 1)
        alpha = int(255 * min(1, a * 2))
        scale_t = ease_out_cubic(1 - a)
        size = int(lerp(64, 44, scale_t))
        if "PATRON" in run.waves.announce_text:
            col = RED
        elif "YOĞUNLUK" in run.waves.announce_text:
            col = ORANGE
        else:
            col = CYAN
        draw_text(surf, run.waves.announce_text, (VIRTUAL_W / 2, VIRTUAL_H / 2 - 40), size, col,
                  bold=True, center=True, alpha=alpha)

    if frac < 0.3 and p.alive:
        pulse = (math.sin(t * 8) + 1) / 2
        vg = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(vg, (180, 0, 0, int(40 * pulse * (1 - frac / 0.3 + 0.3))), vg.get_rect())
        surf.blit(vg, (0, 0))

    if run.fx.flash > 0:
        s = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        s.fill((*run.fx.flash_col, int(run.fx.flash * 130)))
        surf.blit(s, (0, 0))

    if run.ach:
        run.ach.draw(surf)


def draw_invisible_player(world, p, t):
    """GÖRÜNMEZLİK PELERİNİ açıkken oyuncunun hayalet hâli.

    Oyuncu, kendi çizim koduyla geçici bir yüzeye çizilip yarı saydam
    basılıyor: Player.draw() dünya koordinatlarıyla çalıştığı için konumu
    kısa süreliğine yüzeyin ortasına alıyoruz, sonra geri veriyoruz. Böylece
    skin, silah ve kıyafet çizimi tek bir yerde kalıyor — hayalet hâli için
    ikinci bir çizim koduna gerek kalmıyor.

    Oyuncu KENDİNİ görmeye devam etmeli (yoksa nereye gittiğini bilemez);
    düşmanlar için görünmez olması tamamen Enemy.update() tarafında.
    """
    size = 260
    tmp = pygame.Surface((size, size), pygame.SRCALPHA)
    ox, oy = p.x, p.y
    p.x, p.y = size * 0.5, size * 0.5
    try:
        p.draw(tmp, t)
    except Exception:
        p.x, p.y = ox, oy
        p.draw(world, t)         # beklenmedik bir durumda normal çizime dön
        return
    p.x, p.y = ox, oy
    # Süre biterken yavaşça geri belirir: oyuncu ne zaman görüneceğini görsün.
    fade = clamp(p.invis_t / 1.2, 0.0, 1.0)
    tmp.set_alpha(int(lerp(150, 66, fade)))
    world.blit(tmp, (ox - size * 0.5, oy - size * 0.5))
    # çevresinde dönen gizlilik halkası + savrulan zerreler
    pulse = 0.5 + 0.5 * math.sin(t * 3.4)
    add_glow(world, ox, oy, 54, CLOAK_COLOR, 0.18 + 0.10 * pulse)
    for i in range(10):
        a = t * 1.6 + i * math.tau / 10
        rr = 30 + 6 * math.sin(t * 2.6 + i)
        circle_aa(world, ox + math.cos(a) * rr, oy + math.sin(a) * rr * 0.6,
                  1.6 + 1.2 * ((i + int(t * 3)) % 3 == 0), CLOAK_COLOR2)


# Sıralamada ZORLUK rozeti. Zorluk oyunun TEMPOSUNU değiştiriyor (KABUS'ta
# düşmanlar iki kattan fazla hızlı geliyor), yani aynı skor her zorlukta aynı
# şeyi ifade etmiyor. Oyuncu kiminle yarıştığını görsün.
DIFF_BADGE = {"nightmare": ((255, 120, 110), (62, 22, 26)),
              "hard": ((255, 186, 96), (56, 38, 18)),
              "normal": ((150, 190, 235), (22, 32, 50))}


def _lb_diff_badge(surf, cx, y, diff):
    d = str(diff or "normal")
    if d not in DIFF_BADGE:
        d = "normal"
    fg, bg = DIFF_BADGE[d]
    txt = LX("diff." + d, DIFF_LABEL.get(d, d))
    w = int(text_width(txt, 9, True)) + 14
    r = pygame.Rect(int(cx - w / 2), int(y), w, 14)
    pygame.draw.rect(surf, bg, r, border_radius=7)
    pygame.draw.rect(surf, fg, r, width=1, border_radius=7)
    draw_text(surf, txt, r.center, 9, fg, bold=True, center=True, shadow=False)


def draw_run(surf, run, t, aim_pos=None):
    """Koşuyu çizer.

    Bütün dünya nesneleri DÜNYA yüzeyine kendi dünya koordinatlarıyla çizilir;
    sonra yalnızca kameranın gördüğü dikdörtgen ekrana kopyalanır. Böylece
    varlıkların çizim kodu kameradan habersiz kalabiliyor.
    """
    world = world_surface()
    cam = run.cam_rect()
    prev_clip = world.get_clip()
    world.set_clip(cam)

    draw_world_floor(world, cam, run.biome, t)

    if run.hell_portal is not None:
        run.hell_portal.draw(world, t)
    # EKRAN DIŞINI ÇİZME.
    # Dünya ekranın 3x3'ü kadar; kırpma (set_clip) görünmeyen pikselleri atıyor
    # ama Python tarafındaki çizim işi ve her nesnenin parlama blit'i yine de
    # yapılıyordu. Silahlar güçlendikten sonra yerde 400'ü aşkın toplanmamış
    # altın/tecrübe birikiyor ve bunların hepsini her karede çizmek kare
    # süresinin en büyük kalemi hâline geliyor. Görünür alanın biraz dışındaki
    # nesneler artık hiç çizilmiyor.
    vis_near = cam.inflate(200, 200)        # küçük nesneler (eşya, yaratık)
    vis_far = cam.inflate(900, 900)         # geniş alanlar (su, ateş, mühür)

    for hz in run.hazards:
        if vis_far.collidepoint(hz.x, hz.y):
            hz.draw(world, t)
    # --- ZEMİNE ÇİZİLEN SİLAH ALANLARI (varlıkların ALTINDA kalır) ---
    # v3.15: silah görselleri AÇIK / KISIK / KAPALI (Ayarlar). Hasar aynen
    # işler; yalnızca çizim değişir.
    _fxm = weapon_fx_mode()
    _pw = run.player.weapons
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("pentagram", 0) > 0
                           or bool(run.water_zones) or bool(run.fire_rings))
        draw_pentagram_field(world, run.player, t)
        for wz in run.water_zones:
            if vis_far.collidepoint(wz.x, wz.y):
                wz.draw(world, t)
        for fr in run.fire_rings:
            if vis_far.collidepoint(fr.x, fr.y):
                fr.draw(world, t)
        _wfx_end(world, _snap)
    for pu in run.pickups:
        if vis_near.collidepoint(pu.x, pu.y):
            pu.draw(world, t)
    for mg in run.magnets:
        if vis_far.collidepoint(mg.x, mg.y):
            mg.draw(world, t)
    for ch in run.chests:
        ch.draw(world, t)
    # Kalkan kitaplarının yörüngesinin ARKA yarısı oyuncudan önce çizilir.
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("book", 0) > 0)
        draw_shield_books(world, run.player, t, layer="back")
        _wfx_end(world, _snap)
    for e in sorted(run.enemies, key=lambda e: e.y):
        if vis_near.collidepoint(e.x, e.y):
            e.draw(world, t)
    for b in sorted(run.bosses, key=lambda b: b.y):
        if b.alive:
            b.draw(world, t)
    for proj in run.enemy_projectiles:
        if vis_near.collidepoint(proj.x, proj.y):
            proj.draw(world, t)
    for proj in run.player_projectiles:
        if vis_near.collidepoint(proj.x, proj.y):
            proj.draw(world, t)
    if run.player.alive:
        if getattr(run.player, "invis_t", 0.0) > 0:
            draw_invisible_player(world, run.player, t)
        else:
            run.player.draw(world, t)
    # --- PET: oyuncunun yanında gezer (yalnızca görünüş) ---
    draw_run_pet(world, run, t)
    # --- OYUNCUNUN ÜSTÜNE ÇİZİLENLER ---
    if _fxm != "off":
        _snap = _wfx_begin(world, cam, _pw.get("book", 0) > 0 or bool(run.flying_axes)
                           or bool(run.whip_lashes) or bool(run.sword_slashes)
                           or bool(run.tornados))
        draw_shield_books(world, run.player, t, layer="front")
        for ax in run.flying_axes:
            if vis_near.collidepoint(ax.x, ax.y):
                ax.draw(world, t)
        for wl in run.whip_lashes:
            if vis_far.collidepoint(wl.x, wl.y):
                wl.draw(world, t)
        for sl in run.sword_slashes:
            if vis_far.collidepoint(sl.x, sl.y):
                sl.draw(world, t)
        # Hortum en üstte: huni ekranın yukarısına doğru uzanıyor.
        for tn in run.tornados:
            if vis_far.collidepoint(tn.x, tn.y):
                tn.draw(world, t)
        _wfx_end(world, _snap)
    run.fx.draw(world)
    run.fx.draw_texts(world)          # hasar sayıları da dünya koordinatında
    world.set_clip(prev_clip)

    surf.blit(world, VIEW_RECT.topleft, cam)

    # (v3.17: kenar karartması kaldırıldı — bkz. view_vignette)

    draw_offscreen_markers(surf, run, cam, t)
    draw_hud(surf, run, t)
    draw_minimap(surf, run, t)
    # M ile açılan BÜYÜK harita: küçük haritanın aynısı, ekranın ortasında.
    # Oyun bu sırada DURMAZ — harita bir mola değil, bir bakış.
    if getattr(run, "show_map", False):
        draw_minimap(surf, run, t, big=True)
    draw_weapon_slots(surf, run, t)
    draw_book_slots(surf, run, t)
    draw_skill_bar(surf, run, t)
    # İSTATİSTİK paneli en üstte çizilir: açıkken küçük haritayı örter.
    draw_stats_button(surf, run, aim_pos, t)
    if getattr(run, "show_stats", False):
        draw_stats_panel(surf, run, t)

    # (v3.18: nişangah artık BURADA değil, her ekranda tek yerden çiziliyor —
    # bkz. draw_cursor / App.run_loop. Windows imleci tamamen gizli.)


# =====================================================================
# SEVİYE ATLAMA KART SEÇİMİ
# =====================================================================

# ---- SİMGE ÖNBELLEĞİ (HUD) ----------------------------------------
# Silah simgeleri elle çizilmiş vektör şekiller: her biri 20-60 çizim
# çağrısı. HUD şeridinde 8 silah varsa bu KARE BAŞINA ~400 çağrı demek ve
# ölçümde kare süresinin en büyük ikinci kalemiydi. Simge bir kez çizilip
# saklanıyor; HUD artık tek blit yapıyor.
#
# Önbellekteki kopya ZAMANSIZ çizilir (t=0): HUD'daki 20 piksellik simgenin
# kendi içindeki salınım zaten görünmüyordu. Market ve silahlık kartları
# eskisi gibi draw_weapon_sigil'i canlı çağırmaya devam ediyor; orada simge
# büyük ve az sayıda.
_sigil_cache = {}


def sigil_sprite(key, r, col):
    r = max(4, int(r))
    col = (int(col[0]), int(col[1]), int(col[2]))
    ck = (key, r, col)
    s = _sigil_cache.get(ck)
    if s is None:
        if len(_sigil_cache) > 320:
            _sigil_cache.clear()
        pad = int(r * 2.4) + 8
        s = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
        global _GLOW_ON_ALPHA
        _GLOW_ON_ALPHA = True
        try:
            draw_weapon_sigil(s, pad, pad, r, key, col, 0.0)
        finally:
            _GLOW_ON_ALPHA = False
        _sigil_cache[ck] = s
    return s


def blit_sigil(surf, cx, cy, r, key, col):
    """Önbellekten simge basar (HUD için)."""
    s = sigil_sprite(key, r, col)
    w = s.get_width() // 2
    surf.blit(s, (int(cx) - w, int(cy) - w))


def draw_weapon_sigil(surf, cx, cy, r, key, col, t=0.0):
    """Silaha ÖZEL, ELLE ÇİZİLMİŞ sembol.

    Her silahın kendi şekli var: balta gerçekten balta, kalkan gerçekten
    kalkan gibi duruyor. Çizimler düz tek renk dolgu DEĞİL: her yüzey koyu
    kontur + gövde + pah ışığı + keskin parlama katmanlarından geçiyor ve
    kenarları yumuşatılıyor (bkz. poly_aa / metal / wood_shaft). Böylece
    simgeler küçük boyda da "pixel art" gibi değil, boyanmış gibi okunuyor.

    r     : sembolün yaklaşık yarıçapı
    col   : silahın rengi. Kilitli silahlarda SOLUK gelir; malzeme renkleri
            de bu solukluğa göre kısılır, yoksa kilitli kartta çelik pırıl
            pırıl parlıyordu.
    """
    lite = lighten(col, 0.45)
    dark = scale_col(col, 0.58)
    # Malzeme tonları, gelen rengin parlaklığına göre kısılır.
    lum = (col[0] + col[1] + col[2]) / 765.0
    sh = clamp(0.42 + 0.80 * lum, 0.42, 1.0)
    steel = scale_col((214, 226, 244), sh)
    steel_d = scale_col((84, 96, 120), sh)
    gold = scale_col((232, 190, 96), sh)
    timber = scale_col((156, 108, 62), sh)

    if key == "axe":
        # ---------------- SAVAŞ BALTASI ----------------
        # Dik duran ahşap sap + üstüne oturan SAKALLI (bearded) tek ağızlı baş.
        # Ağız sağa doğru geniş bir yay çizer, aşağı uzanan çengeliyle biter;
        # sapın arkasında küçük bir çekiç topuzu, boynunda iki metal bilezik
        # vardır. Şekil önce (0,0) çevresinde kurulur, sonra hafifçe eğilir —
        # böylece balta donuk durmaz ama okunurluğunu hiç kaybetmez.
        tilt = -0.30 + math.sin(t * 1.5) * 0.04

        def P(px, py):
            # rot() ilk iki değeri YEREL sapma sayar, (cx, cy) ise merkezdir.
            return rot(px, py, tilt, cx, cy)

        def Pl(pts):
            return [P(a, b) for a, b in pts]

        # 1) sap (aşağıdan yukarı) + dipteki metal bilezik + kabza sargısı
        butt, top = P(-r * 0.10, r * 0.98), P(-r * 0.10, -r * 0.88)
        wood_shaft(surf, butt, top, r * 0.17, timber)
        leather_wrap(surf, butt, P(-r * 0.10, r * 0.34), r * 0.19, 4,
                     scale_col((104, 66, 46), sh))
        thick_line(surf, P(-r * 0.10, r * 1.00), P(-r * 0.10, r * 0.84),
                   r * 0.23, steel_d)

        # 2) arkadaki çekiç topuzu (poll)
        metal(surf, Pl([(-r * 0.18, -r * 0.78), (-r * 0.18, -r * 0.38),
                        (-r * 0.48, -r * 0.44), (-r * 0.48, -r * 0.74)]),
              steel_d, lite=scale_col(steel, 0.80), spec=False, ow=r * 0.09)

        # 3) ağız: sağa doğru bombeli yay + aşağı uzanan sakal
        # Ağız daire değil HİLAL: yay yatayda basık (0.72), dikeyde tam (1.0).
        arc = []
        for i in range(13):
            th = -1.00 + 2.06 * i / 12.0
            arc.append((r * 0.14 + math.cos(th) * r * 0.72,
                        -r * 0.36 + math.sin(th) * r * 0.86))
        blade = arc + [(r * 0.22, r * 0.46), (r * 0.00, r * 0.06),
                       (r * 0.00, -r * 0.70)]
        metal(surf, Pl(blade), steel, lite=scale_col((248, 251, 255), sh),
              dark=steel_d, ow=r * 0.10, lx=-0.30, ly=-0.60)
        # keskin ağız: yayın tam üstünde bembeyaz ince bir şerit
        taper_line(surf, Pl(arc), max(1.4, r * 0.085), max(1.4, r * 0.085),
                   scale_col((255, 255, 255), sh))
        # ağzın hemen gerisinde silahın renginde ikinci bir hat (tav çizgisi)
        inner = [(r * 0.14 + math.cos(-0.94 + 1.92 * i / 12.0) * r * 0.55,
                  -r * 0.36 + math.sin(-0.94 + 1.92 * i / 12.0) * r * 0.66)
                 for i in range(13)]
        taper_line(surf, Pl(inner), max(1.0, r * 0.05), max(1.0, r * 0.05),
                   scale_col(col, 0.90))

        # 4) boyundaki iki bilezik + perçin
        for yy in (-r * 0.70, -r * 0.34):
            thick_line(surf, P(-r * 0.24, yy), P(r * 0.10, yy), r * 0.10, gold)
        circle_aa(surf, *P(-r * 0.07, -r * 0.52), max(1, r * 0.055),
                  scale_col(gold, 1.15))
        add_glow(surf, *P(r * 0.86, -r * 0.36), r * 0.36, lite, 0.30)

    elif key == "book":
        # ---------------- KALKAN ----------------
        # (Anahtar tarihsel olarak "book"; artık dövme bir KALKAN çiziyor.)
        # Altın kaplamalı çember, ahşap gövde, ortada kubbeli göbek (umbo).
        rr = r * 0.96
        bob = math.sin(t * 2.0) * r * 0.035
        sx, sy = cx, cy + bob
        circle_aa(surf, sx, sy + r * 0.10, rr, OUTLINE)
        # gövde: kenarı koyu, ortası açık — hafif küresel his. Kayma ve
        # yarıçap altın bileziği (rr) TAŞMAYACAK şekilde küçük tutuluyor,
        # yoksa gövde bir tarafta bileziği aşıp kenarı oval gösteriyordu.
        disc_grad(surf, sx - rr * 0.08, sy - rr * 0.09, rr * 0.84,
                  scale_col((178, 200, 230), sh), scale_col((70, 86, 112), sh), 9)
        # dört ahşap tahta (dikey şeritler)
        for i in (-1, 1):
            thick_line(surf, (sx + i * rr * 0.44, sy - rr * 0.80),
                       (sx + i * rr * 0.44, sy + rr * 0.80),
                       max(1.0, rr * 0.06), scale_col((58, 72, 96), sh))
        # altın çember (kaplama) + iç bilezik — bant artık biraz daha kalın,
        # daha "dövme" ve sağlam duruyor.
        ring_aa(surf, sx, sy, rr, scale_col(gold, 0.72), max(2, int(rr * 0.18)))
        ring_aa(surf, sx, sy, rr * 0.90, gold, max(1, int(rr * 0.07)))
        ring_aa(surf, sx, sy, rr * 0.62, scale_col(col, 0.85), max(1, int(rr * 0.05)))
        # perçinler — görünen altın bandın TAM ORTASINDA (eskiden rr*0.80'de
        # duruyordu; bu, bandın iç sınırının (~rr*0.82) altında kalıp
        # perçinlerin ahşap yüzeye taşmış gibi görünmesine yol açıyordu).
        for i in range(8):
            a2 = t * 0.35 + i * math.tau / 8
            px, py = sx + math.cos(a2) * rr * 0.91, sy + math.sin(a2) * rr * 0.91
            circle_aa(surf, px, py, max(1, rr * 0.075), scale_col(gold, 1.10))
            circle_aa(surf, px - rr * 0.02, py - rr * 0.02, max(1, rr * 0.035),
                      scale_col((255, 248, 220), sh))
        # göbek (umbo): kubbe + tepe parlaması
        circle_aa(surf, sx, sy, rr * 0.34, steel_d)
        disc_grad(surf, sx - rr * 0.08, sy - rr * 0.10, rr * 0.30,
                  scale_col((248, 252, 255), sh), scale_col((110, 128, 158), sh), 7)
        circle_aa(surf, sx - rr * 0.10, sy - rr * 0.12, rr * 0.08,
                  scale_col((255, 255, 255), sh))
        # sol üstte keskin bir yansıma yayı
        ring_aa(surf, sx, sy, rr * 0.86, scale_col((255, 255, 255), sh * 0.7), 1)
        add_glow(surf, sx, sy, rr * 1.25, col, 0.16 + 0.08 * math.sin(t * 2.4))

    elif key == "emanet":
        # ---------------- EMANET (miras kılıç) ----------------
        # Düz, ortasında oluk (fuller) olan bir kılıç: sargılı kabza, hafif
        # kıvrık balçak, üstünde taş olan yuvarlak topuz.
        a = -0.78 + math.sin(t * 1.3) * 0.03
        ca, sa = math.cos(a), math.sin(a)
        nx, ny = -sa, ca

        def Q(u, v):
            return (cx + ca * u + nx * v, cy + sa * u + ny * v)

        blade_l = r * 1.16
        halfw = r * 0.155
        # 1) namlu (bıçak): uca doğru sivrilen gövde
        blade = [Q(-r * 0.06, -halfw), Q(blade_l * 0.74, -halfw * 0.72),
                 Q(blade_l, 0.0), Q(blade_l * 0.74, halfw * 0.72),
                 Q(-r * 0.06, halfw)]
        metal(surf, blade, scale_col((226, 236, 250), sh),
              lite=scale_col((255, 255, 255), sh),
              dark=scale_col((104, 118, 146), sh), ow=r * 0.09)
        # oluk (fuller): namlunun ortasında koyu bir kanal + yanında ışık
        thick_line(surf, Q(r * 0.02, 0), Q(blade_l * 0.80, 0), max(1.0, r * 0.07),
                   scale_col((132, 148, 178), sh))
        thick_line(surf, Q(r * 0.04, -halfw * 0.52), Q(blade_l * 0.78, -halfw * 0.40),
                   max(1.0, r * 0.045), scale_col((255, 255, 255), sh))
        # gezinen parlama: kılıcın üstünde ileri geri kayan ışık
        gl = (math.sin(t * 1.9) * 0.5 + 0.5)
        gu = lerp(r * 0.10, blade_l * 0.80, gl)
        thick_line(surf, Q(gu, -halfw * 0.7), Q(gu + r * 0.16, halfw * 0.7),
                   max(1.0, r * 0.05), scale_col((255, 255, 255), sh))
        # 2) balçak (crossguard): iki yana uzanan, uçları hafif kalkık kollar
        guard = [Q(-r * 0.16, -r * 0.54), Q(-r * 0.02, -r * 0.48),
                 Q(-r * 0.02, r * 0.48), Q(-r * 0.16, r * 0.54),
                 Q(-r * 0.24, r * 0.38), Q(-r * 0.24, -r * 0.38)]
        metal(surf, guard, gold, lite=scale_col((255, 240, 180), sh),
              dark=scale_col((130, 96, 40), sh), ow=r * 0.09)
        # 3) kabza: sargılı
        grip0, grip1 = Q(-r * 0.78, 0.0), Q(-r * 0.30, 0.0)
        thick_line(surf, grip0, grip1, r * 0.20, OUTLINE)
        thick_line(surf, grip0, grip1, r * 0.155, scale_col((84, 54, 40), sh))
        leather_wrap(surf, grip0, grip1, r * 0.20, 4, scale_col((126, 84, 58), sh))
        # 4) topuz + taş
        px, py = Q(-r * 0.88, 0.0)
        circle_aa(surf, px, py, r * 0.155, scale_col((132, 98, 42), sh))
        disc_grad(surf, px - r * 0.03, py - r * 0.04, r * 0.13,
                  scale_col((255, 238, 170), sh), scale_col((150, 112, 46), sh), 6)
        circle_aa(surf, px, py, r * 0.065, scale_col(col, 1.0))
        circle_aa(surf, px - r * 0.02, py - r * 0.03, r * 0.03,
                  scale_col((255, 255, 255), sh))
        add_glow(surf, *Q(blade_l, 0.0), r * 0.36, scale_col((236, 246, 255), sh), 0.26)

    elif key == "cloak":
        # ---------------- GÖRÜNMEZLİK PELERİNİ ----------------
        # Boş bir başlık (kukuleta) ve altında dalgalanan kumaş. Kumaş yarı
        # saydam gibi okunsun diye gövde birkaç ton üst üste konuyor ve
        # kenarında sürekli titreyen bir parıltı var.
        sway = math.sin(t * 1.5) * r * 0.06
        top = cy - r * 0.86
        hem = cy + r * 0.92
        body = []
        # sol kenar: omuzdan aşağı
        body.append((cx - r * 0.30, top + r * 0.20))
        body.append((cx - r * 0.66, cy - r * 0.10))
        body.append((cx - r * 0.86 + sway * 0.6, cy + r * 0.44))
        # dalgalı alt kenar
        for i in range(5):
            f = i / 4.0
            xx = cx - r * 0.86 + f * r * 1.72 + sway * (1.0 - abs(f - 0.5) * 2) * 0.5
            yy = hem - (r * 0.20 if i % 2 else 0.0) + math.sin(t * 3 + i * 1.4) * r * 0.05
            body.append((xx, yy))
        body.append((cx + r * 0.86 - sway * 0.6, cy + r * 0.44))
        body.append((cx + r * 0.66, cy - r * 0.10))
        body.append((cx + r * 0.30, top + r * 0.20))
        poly_aa(surf, [(x, y + r * 0.06) for x, y in body], OUTLINE)
        poly_aa(surf, body, scale_col(col, 0.50))
        poly_aa(surf, poly_inset(body, 0.86, dy=-r * 0.03), scale_col(col, 0.78))
        poly_aa(surf, poly_inset(body, 0.50, dx=-r * 0.10, dy=-r * 0.08), col)
        # kıvrımlar
        for i in (-1, 0, 1):
            thick_line(surf, (cx + i * r * 0.34, cy - r * 0.06),
                       (cx + i * r * 0.40 + sway * 0.4, hem - r * 0.14),
                       max(1.0, r * 0.05), scale_col(col, 0.42))
        # başlık: dolu bir kaput, içi karanlık
        hood = [(cx - r * 0.50, cy - r * 0.16), (cx - r * 0.44, top + r * 0.16),
                (cx - r * 0.18, top - r * 0.04), (cx + r * 0.18, top - r * 0.04),
                (cx + r * 0.44, top + r * 0.16), (cx + r * 0.50, cy - r * 0.16)]
        # NOT: başlığın ALTINA gölge kopyası çizilmiyor. Başlık pelerinin
        # üstüne oturduğu için kaydırılmış koyu kopya, kumaşın ortasında
        # baştan başa uzanan sert siyah bir çizgi gibi görünüyordu.
        poly_aa(surf, hood, scale_col(col, 0.62))
        poly_edge(surf, hood, scale_col(col, 0.34), max(1, int(r * 0.05)))
        poly_aa(surf, poly_inset(hood, 0.84, dx=-r * 0.04, dy=-r * 0.04),
                lighten(col, 0.18))
        # kukuletanın içi: tepesi kemerli, altı yuvarlak bir KARANLIK boşluk
        void = []
        for i in range(15):
            th = math.pi * (1.0 + i / 14.0)          # üst yarım kemer
            void.append((cx + math.cos(th) * r * 0.29,
                         cy - r * 0.30 + math.sin(th) * r * 0.26))
        for i in range(9):
            th = math.pi * (i / 8.0)                 # alt yuvarlak (sağdan sola)
            void.append((cx + math.cos(th) * r * 0.29,
                         cy - r * 0.30 + math.sin(th) * r * 0.30))
        poly_aa(surf, void, (10, 10, 18))
        poly_edge(surf, void, scale_col(col, 0.45), 1)
        # içeride iki soluk göz
        eg = 0.55 + 0.45 * math.sin(t * 2.6)
        for sgn in (-1, 1):
            ex, ey = cx + sgn * r * 0.12, cy - r * 0.33
            circle_aa(surf, ex, ey, max(1, r * 0.055), scale_col(lite, 0.5 + 0.5 * eg))
        # kenarda titreyen parıltı
        for i in range(5):
            ph = (t * 0.7 + i * 0.2) % 1.0
            px = cx - r * 0.8 + (i * 0.4 + ph) % 1.6 * r
            py = lerp(cy + r * 0.8, cy - r * 0.5, ph)
            circle_aa(surf, px, py, max(1, r * 0.05 * (1 - ph)), CLOAK_COLOR2)
        add_glow(surf, cx, cy, r * 1.15, col, 0.14 + 0.10 * math.sin(t * 2.0))

    elif key == "pentagram":
        # ---------------- MÜHÜR ----------------
        ang = t * 0.55
        circle_aa(surf, cx, cy, r * 0.98, scale_col(col, 0.16))
        ring_aa(surf, cx, cy, r * 0.98, scale_col(col, 0.85), max(2, int(r * 0.07)))
        ring_aa(surf, cx, cy, r * 0.84, scale_col(lite, 0.6), max(1, int(r * 0.04)))
        pts = [(cx + math.cos(ang - math.pi / 2 + i * math.tau / 5) * r * 0.78,
                cy + math.sin(ang - math.pi / 2 + i * math.tau / 5) * r * 0.78)
               for i in range(5)]
        order = (0, 2, 4, 1, 3, 0)
        for i in range(5):
            thick_line(surf, pts[order[i]], pts[order[i + 1]], max(2.0, r * 0.10),
                       scale_col(col, 0.55))
            thick_line(surf, pts[order[i]], pts[order[i + 1]], max(1.0, r * 0.05), lite)
        for (px, py) in pts:
            add_glow(surf, px, py, r * 0.28, lite, 0.34)
            circle_aa(surf, px, py, max(1, r * 0.10), lite)
            circle_aa(surf, px, py, max(1, r * 0.045), WHITE)
        for i in range(12):
            a2 = -ang * 0.7 + i * math.tau / 12
            c2, s2 = math.cos(a2), math.sin(a2)
            thick_line(surf, (cx + c2 * r * 0.90, cy + s2 * r * 0.90),
                       (cx + c2 * r * 1.00, cy + s2 * r * 1.00),
                       max(1.0, r * 0.05), scale_col(col, 0.75))

    elif key == "whip":
        # ---------------- KIRBAÇ ----------------
        # Örgülü deri kayış: sapı sol altta, ucu sağ üstte sivrilerek biter.
        # Örgü hissi, kayış boyunca DÖNÜŞÜMLÜ iki tonla veriliyor; eskiden
        # kullanılan dik çentikler küçük boyda tırtıla benziyordu.
        pts = []
        for i in range(25):
            f = i / 24.0
            px = cx - r * 0.72 + f * r * 1.62
            py = cy + math.sin(f * math.pi * 1.55 + t * 1.8) * r * 0.42 * (1 - f * 0.30)
            pts.append((px, py))
        taper_line(surf, pts, r * 0.21, max(1.0, r * 0.035), OUTLINE)
        for i in range(len(pts) - 1):
            f = i / float(len(pts) - 2)
            w2 = lerp(r * 0.16, max(1.0, r * 0.025), f)
            thick_line(surf, pts[i], pts[i + 1], w2,
                       scale_col(col, 0.55) if i % 2 == 0 else mix_col(col, lite, 0.45))
        # üstte ince bir ışık hattı — kayışın yuvarlaklığını verir
        taper_line(surf, [(x, y - r * 0.045) for x, y in pts], r * 0.07,
                   max(1.0, r * 0.015), lite)
        # sap: ahşap + sargı + metal dip
        h0 = (pts[0][0] - r * 0.42, pts[0][1] + r * 0.20)
        wood_shaft(surf, h0, pts[0], r * 0.20, timber)
        leather_wrap(surf, h0, pts[0], r * 0.22, 3, scale_col((112, 72, 48), sh))
        circle_aa(surf, h0[0], h0[1], r * 0.12, steel_d)
        circle_aa(surf, h0[0] - r * 0.02, h0[1] - r * 0.03, r * 0.05,
                  scale_col(steel, 1.0))
        # uçtaki kamçı (popper)
        ex, ey = pts[-1]
        for sgn in (-1, 1):
            thick_line(surf, (ex, ey), (ex + r * 0.22, ey + sgn * r * 0.13),
                       max(1.0, r * 0.028), lite)
        add_glow(surf, ex, ey, r * 0.34, WHIP_COLOR2, 0.38 + 0.2 * math.sin(t * 6))

    elif key == "zemzem":
        # ---------------- ZEMZEM (kutsal su) ----------------
        # Tepesi sivri, altı yuvarlak gerçek bir DAMLA: alttaki çemberin
        # neredeyse tamamı çizilir, iki ucu tepedeki sivri noktada birleşir.
        bx, by, br = cx, cy + r * 0.20, r * 0.56
        drop = [(cx, cy - r * 0.96)]
        for i in range(19):
            th = -0.52 + (math.pi + 1.04) * i / 18.0
            drop.append((bx + math.cos(th) * br, by + math.sin(th) * br))
        poly_aa(surf, [(x, y + r * 0.06) for x, y in drop], OUTLINE)
        poly_aa(surf, drop, scale_col(col, 0.52))
        poly_aa(surf, poly_inset(drop, 0.82, dy=-r * 0.02), col)
        poly_aa(surf, poly_inset(drop, 0.46, dx=-r * 0.10, dy=-r * 0.14), lite)
        # iki yansıma: biri geniş, biri nokta
        circle_aa(surf, cx - r * 0.18, cy + r * 0.06, r * 0.13,
                  scale_col((255, 255, 255), sh))
        circle_aa(surf, cx + r * 0.18, cy + r * 0.32, r * 0.055,
                  scale_col((255, 255, 255), sh * 0.85))
        add_glow(surf, cx, cy + r * 0.1, r * 0.80, col, 0.22)
        # altında yayılan halkalar
        for i in range(2):
            ph = (t * 0.7 + i * 0.5) % 1.0
            rr = r * (0.40 + 0.60 * ph)
            pygame.draw.ellipse(surf, scale_col(col, 0.26 + 0.48 * (1 - ph)),
                                (int(cx - rr), int(cy + r * 0.80 - rr * 0.24),
                                 int(rr * 2), int(rr * 0.48)), 2)

    elif key == "shoe":
        # ---------------- BARAN'IN PAPUCU ----------------
        # Yandan görünen YASSI bir papuç: kalın deri taban, alçak yüz ve
        # yukarı kıvrık sivri burun. Arkasından (topuk tarafından) üç alev
        # dili yükselir — papucun bıraktığı ateş izinin işareti.
        for i in range(3):
            fl = 1.0 + 0.26 * math.sin(t * 7 + i * 1.7)
            bxx = cx - r * 0.86 + i * r * 0.28
            flame = [(bxx - r * 0.12, cy + r * 0.54),
                     (bxx - r * 0.02, cy - r * 0.16 * fl),
                     (bxx + r * 0.07, cy - r * 0.76 * fl),
                     (bxx + r * 0.17, cy - r * 0.12 * fl),
                     (bxx + r * 0.22, cy + r * 0.54)]
            poly_aa(surf, flame, scale_col(SHOE_COLOR, 0.80 * sh))
            poly_aa(surf, poly_inset(flame, 0.52, dy=r * 0.10),
                    scale_col(SHOE_COLOR2, sh))
        # taban — uçta yukarı kıvrılır
        sole = [(-0.78, 0.30), (0.80, 0.18), (1.06, -0.06), (1.10, 0.14),
                (0.86, 0.44), (-0.74, 0.52)]
        sole = [(cx + a * r, cy + b * r) for a, b in sole]
        poly_aa(surf, [(x, y + r * 0.06) for x, y in sole], OUTLINE)
        poly_aa(surf, sole, scale_col((86, 56, 38), sh))
        poly_aa(surf, poly_inset(sole, 0.84, dy=-r * 0.04),
                scale_col((126, 82, 52), sh))
        # yüz (papucun üstü) — alçak ve yassı, burnu sivri
        upper = [(-0.74, 0.34), (-0.72, 0.06), (-0.48, -0.12), (-0.06, -0.20),
                 (0.36, -0.10), (0.74, 0.06), (1.02, -0.04), (0.84, 0.24),
                 (-0.66, 0.38)]
        upper = [(cx + a * r, cy + b * r) for a, b in upper]
        poly_aa(surf, [(x, y + r * 0.05) for x, y in upper], OUTLINE)
        poly_aa(surf, upper, scale_col((166, 56, 48), sh))
        poly_aa(surf, poly_inset(upper, 0.86, dx=-r * 0.02, dy=-r * 0.05),
                scale_col((212, 80, 64), sh))
        poly_aa(surf, poly_inset(upper, 0.42, dx=-r * 0.12, dy=-r * 0.09),
                scale_col((242, 126, 94), sh))
        # taban dikişi + yüzdeki altın işleme
        for i in range(8):
            f = i / 7.0
            circle_aa(surf, lerp(cx - r * 0.60, cx + r * 0.80, f),
                      lerp(cy + r * 0.38, cy + r * 0.18, f),
                      max(1, r * 0.026), scale_col(gold, 1.05))
        for i in range(3):
            circle_aa(surf, cx + r * (-0.16 + i * 0.22), cy + r * 0.02,
                      max(1, r * 0.05), gold)
        # burun ucundaki püskül
        circle_aa(surf, cx + r * 1.04, cy - r * 0.06, max(1, r * 0.08), gold)
        add_glow(surf, cx - r * 0.6, cy, r * 0.8, SHOE_COLOR, 0.26)

    elif key == "frost":
        # ---------------- BUZ KRİSTALİ ----------------
        ice = scale_col((226, 246, 255), sh)
        for i in range(6):
            a = t * 0.4 + i * math.tau / 6
            ex, ey = cx + math.cos(a) * r * 0.94, cy + math.sin(a) * r * 0.94
            thick_line(surf, (cx, cy), (ex, ey), max(2.0, r * 0.13), scale_col(col, 0.75))
            thick_line(surf, (cx, cy), (ex, ey), max(1.0, r * 0.06), ice)
            for f, ln in ((0.40, 0.30), (0.64, 0.24), (0.84, 0.16)):
                mx, my = cx + math.cos(a) * r * f, cy + math.sin(a) * r * f
                for sgn in (-1, 1):
                    a2 = a + sgn * 0.68
                    thick_line(surf, (mx, my),
                               (mx + math.cos(a2) * r * ln, my + math.sin(a2) * r * ln),
                               max(1.0, r * 0.045), mix_col(col, ice, 0.5))
        # ortada altı köşeli çekirdek
        hexp = [(cx + math.cos(t * 0.4 + i * math.tau / 6) * r * 0.22,
                 cy + math.sin(t * 0.4 + i * math.tau / 6) * r * 0.22) for i in range(6)]
        poly_aa(surf, hexp, scale_col(col, 0.9))
        poly_aa(surf, poly_inset(hexp, 0.58, dx=-r * 0.03, dy=-r * 0.04), ice)
        add_glow(surf, cx, cy, r * 0.8, col, 0.24)

    elif key == "tornado":
        # ---------------- HORTUM ----------------
        # Aşağı doğru daralan DOLU bir huni: gövde tek parça çizilir, üstüne
        # dönen bantlar ve savrulan kırıntılar konur. Eskiden yalnızca çember
        # konturları çiziliyordu ve simge yaylı bir zemberek gibi okunuyordu.

        def fun_x(f):
            return cx + math.sin(t * 3.0 - f * 3.4) * r * 0.14 * f

        def fun_y(f):
            return cy + r * 0.84 - f * r * 1.64

        def fun_w(f):
            return r * (0.13 + 0.84 * f)

        right, left = [], []
        for i in range(9):
            f = i / 8.0
            right.append((fun_x(f) + fun_w(f), fun_y(f)))
            left.append((fun_x(f) - fun_w(f), fun_y(f)))
        body = right + left[::-1]
        poly_aa(surf, body, scale_col(col, 0.34))
        poly_aa(surf, poly_inset(body, 0.78, dx=-r * 0.05), scale_col(col, 0.52))
        # dönen bantlar: huninin ön yüzünde soldan sağa geçen yaylar
        for i in range(6):
            f = 0.10 + i * 0.16
            ww, yy, xx = fun_w(f), fun_y(f), fun_x(f)
            band = [(xx + math.cos(th) * ww, yy + math.sin(th) * ww * 0.34)
                    for th in [j * math.pi / 8 for j in range(9)]]
            taper_line(surf, band, max(1.4, r * 0.075), max(1.4, r * 0.075),
                       mix_col(col, lite, f))
        # tepedeki ağız
        topw, topy, topx = fun_w(1.0), fun_y(1.0), fun_x(1.0)
        ring = [(topx + math.cos(th) * topw, topy + math.sin(th) * topw * 0.34)
                for th in [j * math.tau / 20 for j in range(21)]]
        taper_line(surf, ring, max(1.4, r * 0.07), max(1.4, r * 0.07), lite)
        # savrulan kırıntılar
        for i in range(7):
            ph = (t * 0.9 + i * 0.143) % 1.0
            th = t * 5 + i * 1.7
            circle_aa(surf, fun_x(ph) + math.cos(th) * fun_w(ph) * 1.12,
                      fun_y(ph) + math.sin(th) * fun_w(ph) * 0.34,
                      max(1, r * 0.06 * (1 - ph * 0.5)), lite)
        # tabanda savrulan toz
        pygame.draw.ellipse(surf, scale_col(col, 0.55),
                            (int(cx - r * 0.44), int(cy + r * 0.76),
                             int(r * 0.88), int(r * 0.26)), 2)
        add_glow(surf, cx, cy - r * 0.2, r * 0.9, col, 0.16)

    else:
        draw_icon(surf, cx, cy, "star", col, int(r))


def draw_weapon_emblem(surf, cx, cy, h, w, t=0.0, locked=False, glow=True):
    """Bir silahın ARMASI: dövme madalyon + silaha özel sembol + ışık.

    Kitapların draw_book'una karşılık gelen silah karşılığıdır; hem seviye
    atlama kartlarında hem de SİLAHLIK ekranında kullanılır. h, madalyonun
    yaklaşık yüksekliğidir.

    Madalyon düz bir daire değil: dışta dönen kertikler, altın bir bilezik
    (üstü aydınlık, altı gölgede), dört perçin ve içeride merkeze doğru
    açılan bir zemin var. Kilitliyken bütün katmanlar söner ve üstüne bir
    asma kilit oturur.
    """
    r = h * 0.46
    col = tuple(w["color"])
    if locked:
        col = scale_col(col, 0.34)
    pulse = 0.5 + 0.5 * math.sin(t * 2.4 + cx * 0.01)
    if glow and not locked:
        add_glow(surf, cx, cy, r * 1.95, col, 0.24 + 0.16 * pulse)

    # Gövdenin ana yarıçapları — tek yerden türetiliyor ki bilezik, perçin ve
    # ışık/gölge kavisleri hep AYNI orana göre otursun (daha dengeli, "kalın
    # ve düzgün" bir altın bant; eskiden bant r+3 / r*0.94 arasıydı, yani
    # yarıçapın yalnızca ~%14'ü kadardı — ince ve cansız duruyordu).
    R_OUT = r * 1.10          # bileziğin dış sınırı
    R_IN = r * 0.88           # bileziğin iç sınırı (koyu yüzün başladığı yer)
    R_BAND = (R_OUT + R_IN) * 0.5

    # 1) dış kertikler — yavaşça dönen, yumuşak tırnaklar
    for i in range(16):
        a = t * 0.42 + i * math.tau / 16
        long_tick = (i % 2 == 0)
        r0 = R_OUT * 1.04
        r1 = r0 + r * ((0.20 if long_tick else 0.12) + 0.03 * pulse)
        thick_line(surf, (cx + math.cos(a) * r0, cy + math.sin(a) * r0),
                   (cx + math.cos(a) * r1, cy + math.sin(a) * r1),
                   1.8 if long_tick else 1.1,
                   scale_col(col, 0.45 + 0.40 * pulse))

    # 2) gövde: kontur + altın bilezik (üstü ışıklı, altı gölgeli) + iç zemin
    # NOT (v3.9 düzeltme): dış halka eskiden merkezden KAYDIRILMIŞ bir daire
    # ile "ışık" taklit ediyordu. Neredeyse aynı yarıçaptaki iki daireyi eş
    # merkezli çizmeyince kenar bir tarafta ince bir tarafta kalın çıkıyor,
    # madalyon gerçek bir daire değil hafif yumurta gibi görünüyordu. Artık
    # dış hat TEK ve TAM EŞ MERKEZLİ; ışık/gölge kenara taşmayan ince birer
    # KAVİS (parça) olarak, karşılıklı iki tarafa ekleniyor.
    circle_aa(surf, cx, cy + 2, R_OUT + 3, OUTLINE)
    rim_lo = scale_col(col, 0.34)
    rim_hi = lighten(col, 0.52)
    circle_aa(surf, cx, cy, R_OUT, rim_lo)
    hi_pts = [(cx + math.cos(a) * (R_BAND + 1.2), cy + math.sin(a) * (R_BAND + 1.2))
              for a in [math.pi * (1.04 + i * 0.055) for i in range(10)]]
    taper_line(surf, hi_pts, R_OUT - R_IN, R_OUT - R_IN, mix_col(rim_lo, rim_hi, 0.80))
    sh_pts = [(cx + math.cos(a) * (R_BAND + 1.2), cy + math.sin(a) * (R_BAND + 1.2))
              for a in [math.pi * (0.06 + i * 0.045) for i in range(9)]]
    taper_line(surf, sh_pts, (R_OUT - R_IN) * 0.85, (R_OUT - R_IN) * 0.85,
               scale_col(rim_lo, 0.55))
    circle_aa(surf, cx, cy, R_IN, scale_col(col, 0.20))
    # iç zemin: merkeze doğru açılan koyu bir çanak. Kayma ve yarıçap artık
    # dış gövde dairesini (R_IN) HİÇ AŞMAYACAK şekilde küçük tutuluyor —
    # eskiden gövdeyi taşıp altın bileziğe bindiriyor, o tarafta halkayı
    # daha da incelmiş gösteriyordu.
    disc_grad(surf, cx - r * 0.04, cy - r * 0.05, R_IN * 0.90,
              scale_col(col, 0.46 if not locked else 0.30),
              (14, 15, 24), 9)
    # iç bilezik
    ring_aa(surf, cx, cy, R_IN * 0.98, scale_col(col, 0.85), max(1, int(r * 0.055)))
    ring_aa(surf, cx, cy, R_IN * 0.80, scale_col(col, 0.40), 1)

    # 3) dört perçin — artık kalınlaşan altın bandın TAM ORTASINDA
    for i in range(4):
        a = math.pi / 4 + i * math.pi / 2
        px, py = cx + math.cos(a) * R_BAND, cy + math.sin(a) * R_BAND
        circle_aa(surf, px, py, max(2, r * 0.085), scale_col(col, 0.30))
        circle_aa(surf, px - r * 0.02, py - r * 0.02, max(1, r * 0.05),
                  lighten(col, 0.45))

    # 4) silaha özel sembol. Kilitliyken söner ve yukarı kayar: kilit
    #    gövdesinin altında kalmasın, ikisi birbirini ezmesin.
    sig_y = cy if not locked else cy - r * 0.24
    draw_weapon_sigil(surf, cx, sig_y, r * (0.64 if not locked else 0.46), w["key"],
                      lighten(col, 0.20) if not locked else scale_col(col, 0.60), t)

    # 5) cam parlaması: sol üstte ince bir yansıma yayı
    if not locked:
        arc_pts = [(cx + math.cos(a) * R_IN * 0.90, cy + math.sin(a) * R_IN * 0.90)
                   for a in [math.pi * (1.02 + i * 0.030) for i in range(10)]]
        taper_line(surf, arc_pts, 2.0, 0.8, (255, 255, 255))

    if locked:
        # ASMA KİLİT — madalyonun alt yarısına oturur: gövde + kemer + delik.
        bw = r * 0.46
        bh = r * 0.34
        by = cy + r * 0.32
        sh_ = r * 0.34
        arc_r = pygame.Rect(int(cx - bw * 0.62), int(by - bh - sh_),
                            int(bw * 1.24), int(sh_ * 2))
        pygame.draw.arc(surf, OUTLINE, arc_r.inflate(4, 4), 0.12, math.pi - 0.12,
                        max(3, int(r * 0.13)))
        pygame.draw.arc(surf, (196, 200, 222), arc_r, 0.12, math.pi - 0.12,
                        max(2, int(r * 0.09)))
        body = [(cx - bw, by - bh), (cx + bw, by - bh),
                (cx + bw, by + bh), (cx - bw, by + bh)]
        metal(surf, body, (214, 198, 132), lite=(252, 244, 196),
              dark=(128, 112, 62), spec=False, ow=r * 0.10)
        circle_aa(surf, cx, by - bh * 0.18, max(1, r * 0.09), (54, 44, 28))
        poly_aa(surf, [(cx - r * 0.05, by - bh * 0.10), (cx + r * 0.05, by - bh * 0.10),
                       (cx + r * 0.03, by + bh * 0.52), (cx - r * 0.03, by + bh * 0.52)],
                (54, 44, 28))


class LevelUpOverlay:
    """Seviye atlama ekranı.

    Kartlarda artık hem KİTAP hem SİLAH çıkar. Altta iki düğme var:
      YENİLE : eli baştan dağıtır (ilk 3 bedava, sonrası altınla)
      PAS GEÇ: bu seviyeyi atlar   (ilk 3 bedava, sonrası altınla)
    Dönüş değeri: ("pick", indeks) | ("reroll", None) | ("skip", None) | None
    """

    def __init__(self):
        self.cards = []
        self.btn_reroll = pygame.Rect(0, 0, 0, 0)
        self.btn_skip = pygame.Rect(0, 0, 0, 0)
        self.toast = ""
        self.toast_t = 0.0

    def rebuild(self, choices):
        self.cards = []
        n = max(1, len(choices))
        card_w, card_h = 262, 340
        gap = 28
        total_w = n * card_w + (n - 1) * gap
        start_x = VIRTUAL_W / 2 - total_w / 2
        top = VIRTUAL_H / 2 - card_h / 2 - 14
        for i, ch in enumerate(choices):
            rect = pygame.Rect(start_x + i * (card_w + gap), top, card_w, card_h)
            self.cards.append((rect, ch, i))
        bw, bh = 230, 48
        by = top + card_h + 26
        self.btn_reroll = pygame.Rect(VIRTUAL_W / 2 - bw - 12, by, bw, bh)
        self.btn_skip = pygame.Rect(VIRTUAL_W / 2 + 12, by, bw, bh)

    def _draw_action(self, surf, rect, label, free_left, cost, gold, mouse_pos, base_col):
        """Alttaki YENİLE / PAS GEÇ düğmesi."""
        hover = rect.collidepoint(mouse_pos)
        afford = cost <= gold
        col = base_col if afford else (96, 78, 86)
        panel(surf, rect, bg=(34, 38, 58) if (hover and afford) else (20, 22, 34),
              edge=lighten(col, 0.25) if hover else col, alpha=242, radius=12, edge_w=2)
        draw_text(surf, label, (rect.centerx, rect.y + 8), 18,
                  TEXT if afford else (150, 130, 140), bold=True, center=True)
        if free_left > 0:
            sub = f"{free_left} bedava hakkın var"
            scol = GREEN
        elif cost <= 0:
            sub = "bedava"
            scol = GREEN
        else:
            sub = f"{cost} altın"
            scol = GOLD if afford else (190, 120, 120)
        draw_text(surf, sub, (rect.centerx, rect.bottom - 21), 13, scol,
                  bold=True, center=True, shadow=False)
        return hover and afford

    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        overlay = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(overlay, (5, 6, 12, 196), overlay.get_rect())
        surf.blit(overlay, (0, 0))

        top = self.cards[0][0].y if self.cards else VIRTUAL_H / 2 - 156
        draw_text(surf, L("ui.levelup"), (VIRTUAL_W / 2, top - 86), 40, GOLD,
                  bold=True, center=True)
        p = run.player
        n_w = len(p.weapons)
        n_b = p.normal_book_count()
        n_r = p.rare_book_count()
        sub = (f"SİLAH {n_w}/{MAX_RUN_WEAPONS}"
               f"   •   KİTAP {n_b}/{MAX_RUN_BOOKS}"
               f"   •   NADİR {n_r}/{MAX_RUN_RARE_BOOKS}")
        draw_text(surf, sub, (VIRTUAL_W / 2, top - 48), 16, TEXT_DIM, center=True)
        if n_r >= MAX_RUN_RARE_BOOKS:
            hint = "Nadir kitabını seçtin — bu koşuda başka nadir kitap çıkmaz."
        elif n_w >= MAX_RUN_WEAPONS and n_b >= MAX_RUN_BOOKS:
            hint = "Yuvaların dolu — artık yalnızca yükseltme gelir."
        else:
            hint = "Kitaplar 15. seviyeye kadar büyür; nadir kitaptan yalnızca bir tane alırsın."
        draw_text(surf, hint, (VIRTUAL_W / 2, top - 30), 12,
                  (190, 170, 120) if n_r >= MAX_RUN_RARE_BOOKS else (120, 126, 150),
                  center=True, shadow=False)
        # cepteki altın: yenileme/pas bedelleri buradan ödenir
        draw_coin_label(surf, VIRTUAL_W / 2, top - 11, fmt_num(run.gold_wallet),
                        GOLD, 17, icon_r=8)

        result = None
        for rect, ch, idx in self.cards:
            hover = rect.collidepoint(mouse_pos)
            bob = math.sin(t * 3 + rect.x * 0.01) * 3
            r2 = rect.move(0, bob)
            is_weapon = ch["kind"] == "weapon"
            rare = ch.get("rare")
            col = ch["color"]
            if hover:
                bg = (40, 34, 20) if rare else ((30, 40, 54) if is_weapon else (34, 38, 60))
            else:
                bg = (22, 24, 40)
            panel(surf, r2, bg=bg,
                  edge=(col if hover else (GOLD_DIM if rare else PANEL_EDGE)),
                  alpha=245, radius=18, edge_w=3)

            # ---- üst etiket: SİLAH / YÜKSELTME / NADİR KİTAP / KİTAP ----
            if is_weapon:
                lbl = "YENİ SİLAH" if ch["new"] else f"SİLAH  Lv.{ch['lvl']}"
                lcol = col
            elif rare:
                lbl = "NADİR KİTAP  —  TEK HAK"
                lcol = GOLD
            elif ch.get("new"):
                lbl = "YENİ KİTAP"
                lcol = lighten(col, 0.2)
            else:
                lbl = f"KİTAP  Lv.{ch['lvl']}"
                lcol = TEXT_DIM
            lw = text_width(lbl, 13, True)
            draw_icon(surf, r2.centerx - lw / 2 - 11, r2.y + 24,
                      "sword" if is_weapon else "star", lcol, 6)
            draw_text(surf, lbl, (r2.centerx + 6, r2.y + 18), 13, lcol,
                      bold=True, center=True, shadow=False)

            # ---- görsel ----
            if is_weapon:
                draw_weapon_emblem(surf, r2.centerx, r2.y + 92, 100 if hover else 94,
                                   ch["w"], t)
            else:
                draw_book(surf, r2.centerx, r2.y + 88, 96 if hover else 90, ch["book"], t)

            draw_text(surf, ch["name"], (r2.centerx, r2.y + 152), 20, TEXT,
                      bold=True, center=True)
            for i, ln in enumerate(wrap_text(ch["desc"], 14, r2.w - 40)[:4]):
                draw_text(surf, ln, (r2.centerx, r2.y + 188 + i * 19), 14, TEXT_DIM,
                          center=True, shadow=False)

            # ---- yükseltmelerde mevcut seviye çubuğu (silah ve kitap) ----
            if not ch.get("new"):
                mx = weapon_max_level(ch["w"]) if is_weapon else ch.get("max", BOOK_MAX_LEVEL)  # kart zaten book_max_level ile doldu
                pb = pygame.Rect(r2.x + 30, r2.bottom - 66, r2.w - 60, 8)
                draw_bar(surf, pb, clamp(ch["lvl"] / max(1, mx), 0, 1), col, radius=4)
                draw_text(surf, L("ui.lvl_arrow", ch["lvl"] - 1, ch["lvl"], mx),
                          (r2.centerx, r2.bottom - 56), 11, TEXT_DIM, center=True, shadow=False)
            elif not is_weapon:
                slot_txt = ("bu koşudaki TEK nadir kitabın olur"
                            if rare else
                            f"kitap yuvası {run.player.normal_book_count() + 1}"
                            f"/{MAX_RUN_BOOKS}  —  Lv.{BOOK_MAX_LEVEL}'e kadar büyür")
                draw_text(surf, slot_txt, (r2.centerx, r2.bottom - 60), 11,
                          GOLD_DIM if rare else TEXT_DIM, center=True, shadow=False)

            if hover:
                pygame.draw.rect(surf, col, (r2.x + 16, r2.bottom - 46, r2.w - 32, 32),
                                 border_radius=10)
                draw_text(surf, L("ui.pick"), (r2.centerx, r2.bottom - 30), 16, (10, 10, 16),
                          bold=True, center=True)
                if clicked:
                    result = ("pick", idx)

        # ---- YENİLE / PAS GEÇ ----
        rc, sc = run.reroll_cost(), run.skip_cost()
        hov_r = self._draw_action(surf, self.btn_reroll, L("ui.reroll"),
                                  run.rerolls_left_free(), rc, run.gold_wallet,
                                  mouse_pos, (86, 132, 176))
        hov_s = self._draw_action(surf, self.btn_skip, L("ui.skip"),
                                  run.skips_left_free(), sc, run.gold_wallet,
                                  mouse_pos, (150, 118, 76))
        if clicked and result is None:
            if hov_r:
                result = ("reroll", None)
            elif hov_s:
                result = ("skip", None)

        # ---- kısa bilgi yazısı (yetersiz altın vb.) ----
        if self.toast_t > 0:
            self.toast_t = max(0.0, self.toast_t - 1 / 60.0)
            draw_text(surf, self.toast, (VIRTUAL_W / 2, self.btn_skip.bottom + 16), 15,
                      (240, 200, 120), bold=True, center=True)
        return result

    def say(self, msg):
        self.toast = msg
        self.toast_t = 1.6


# =====================================================================
# OYUN-İÇİ MARKET EKRANI
# =====================================================================

class RunShopOverlay:
    """Oyun-içi market ekranı.

    CEHENNEM'de açıldığında (ya da CEHENNEM sekmesi seçiliyken) ekran
    tamamen kızıla döner: zemin kor rengine boyanır, havada kıvılcımlar
    süzülür, kartların kenarları ergimiş gibi yanar. Amaç, 2. haritanın
    kendi kimliğinin markette de sürmesi.

    Bir kategoride 10'dan fazla eşya varsa alt kısımda SAYFA okları belirir.
    """

    COLS = 5
    ROWS = 2

    def __init__(self):
        self.tab = next(iter(SHOP_CATS))
        self.page = 0

    # ---------------- yardımcılar ----------------
    @staticmethod
    def _hellish(run, tab):
        """Market kızıl temaya bürünsün mü?"""
        return run.biome == "hell" or tab == "hell"

    def _draw_backdrop(self, surf, hellish, t):
        overlay = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        if hellish:
            # kızıl degrade + alttan yükselen kor parıltısı
            for y in range(0, VIRTUAL_H, 4):
                k = y / VIRTUAL_H
                pygame.draw.rect(overlay, (int(26 + 34 * k), int(6 + 8 * k), int(8 + 6 * k), 232),
                                 pygame.Rect(0, y, VIRTUAL_W, 4))
            glow = pygame.Surface((VIRTUAL_W, 220), pygame.SRCALPHA)
            for i in range(220):
                a = int(46 * (i / 219.0) ** 2 * (0.75 + 0.25 * math.sin(t * 1.4)))
                pygame.draw.line(glow, (255, 96, 36, a), (0, i), (VIRTUAL_W, i))
            overlay.blit(glow, (0, VIRTUAL_H - 220))
        else:
            pygame.draw.rect(overlay, (5, 6, 12, 205), overlay.get_rect())
        surf.blit(overlay, (0, 0))
        if hellish:
            # havada süzülen kıvılcımlar
            for i in range(46):
                ph = (t * 0.30 + i * 0.0217) % 1.0
                ex = (i * 197 + math.sin(t * 0.7 + i) * 40) % VIRTUAL_W
                ey = VIRTUAL_H - ph * (VIRTUAL_H + 60)
                blit_disc(surf, ex, ey, 1.4 + 2.2 * (1 - ph),
                          (255, 170 - (int(60 * ph) // 24) * 24, 70), int(210 * (1 - ph)))

    def _draw_header(self, surf, run, hellish, t):
        if hellish:
            title, tcol = "CEHENNEM MARKETİ", (255, 132, 56)
            pulse = 0.55 + 0.45 * math.sin(t * 2.6)
            add_glow(surf, VIRTUAL_W / 2, 48, 210, (255, 90, 40), 0.18 + 0.10 * pulse)
            # başlığın iki yanında alev dilleri
            for sgn in (-1, 1):
                bx = VIRTUAL_W / 2 + sgn * 168
                for i in range(3):
                    h = 22 + 12 * math.sin(t * 7 + i * 1.5 + (0 if sgn > 0 else 2.0))
                    pygame.draw.polygon(surf, (255, 150 - i * 26, 50),
                                        [(bx + i * 9 * sgn, 60), (bx + 4 * sgn + i * 9 * sgn, 60 - h),
                                         (bx + 9 * sgn + i * 9 * sgn, 60)])
        else:
            title, tcol = L("ui.market"), GOLD
        draw_text(surf, title, (VIRTUAL_W / 2, 22), 32, tcol, bold=True, center=True)
        # başlığın altında iki yana açılan ince ayraç
        for sgn in (-1, 1):
            x0 = VIRTUAL_W / 2 + sgn * 108
            taper_line(surf, [(x0, 58), (x0 + sgn * 150, 58)], 2.4, 0.6,
                       scale_col(tcol, 0.85))
            circle_aa(surf, x0 + sgn * 154, 58, 2.5, tcol)
        # ALTIN KESESİ: fiyatlarla aynı dilde bir pastil
        purse_txt = fmt_num(run.gold_wallet)
        purse = pygame.Rect(0, 0, int(coin_label_width(purse_txt, 20, 9)) + 32, 32)
        purse.center = (VIRTUAL_W / 2, 58)
        pss = pygame.Surface(purse.size, pygame.SRCALPHA)
        pygame.draw.rect(pss, (10, 9, 14, 210), pss.get_rect(), border_radius=16)
        surf.blit(pss, purse.topleft)
        pygame.draw.rect(surf, GOLD, purse, width=2, border_radius=16)
        draw_coin_label(surf, purse.centerx, purse.centery, purse_txt, GOLD, 20,
                        icon_r=9)
        sub = L("ui.market_note_hell") if hellish else L("ui.market_note")
        draw_text(surf, sub, (VIRTUAL_W / 2, 80), 12,
                  (226, 150, 120) if hellish else TEXT_DIM, center=True)

    def _draw_tabs(self, surf, run, mouse_pos, clicked, hellish, t):
        tabs = [(k, LX("cat." + k, v)) for k, v in SHOP_CATS.items()]
        tab_w, tab_h, tab_gap = 118, 30, 7
        total_tw = len(tabs) * tab_w + (len(tabs) - 1) * tab_gap
        tx0 = VIRTUAL_W / 2 - total_tw / 2
        ty = 102
        counts = {}
        for it in run.shop_offers:
            counts[it["cat"]] = counts.get(it["cat"], 0) + 1
        for i, (key, label) in enumerate(tabs):
            r = pygame.Rect(tx0 + i * (tab_w + tab_gap), ty, tab_w, tab_h)
            active = (self.tab == key)
            hover = r.collidepoint(mouse_pos)
            is_hell_tab = (key == "hell")
            # CEHENNEM sekmesi 2. haritada erişilebilir; arenada kilitli görünür
            locked = is_hell_tab and run.biome != "hell"
            if is_hell_tab:
                base = (128, 40, 18) if active else ((72, 26, 16) if hover else (44, 18, 14))
                edge = (255, 120, 50) if (active or hover) else (128, 58, 34)
            else:
                base = (90, 70, 30) if active else ((40, 44, 64) if hover else (24, 26, 42))
                edge = GOLD if active else PANEL_EDGE
            if locked:
                base, edge = (30, 20, 22), (92, 54, 44)
            pygame.draw.rect(surf, base, r, border_radius=8)
            pygame.draw.rect(surf, edge, r, width=2, border_radius=8)
            if is_hell_tab and not locked:
                add_glow(surf, r.centerx, r.centery, 34, (255, 110, 50),
                         0.20 + 0.10 * math.sin(t * 3))
                draw_icon(surf, r.x + 15, r.centery, "flame", (255, 150, 60), 8)
            if active:
                # etkin sekmenin altında ince bir vurgu çizgisi
                pygame.draw.rect(surf, edge, (r.x + 10, r.bottom - 4, r.w - 20, 3),
                                 border_radius=2)
            txt_col = TEXT if active else (TEXT_DIM if not locked else (120, 86, 80))
            draw_text(surf, label, (r.centerx + (6 if is_hell_tab else 0), r.centery - 3),
                      12, txt_col, bold=active, center=True, shadow=False)
            n_cat = counts.get(key, 0)
            if n_cat and not locked:
                # Sayı rozeti etkin olmayan sekmelerde de okunmalı: sekmenin
                # kendi kenar rengi koyu olduğu için sabit bir soluk ton.
                draw_text(surf, str(n_cat), (r.right - 13, r.y + 3), 9,
                          lighten(edge, 0.35) if active else (128, 134, 162),
                          bold=True, center=True, shadow=False)
            if clicked and hover:
                if self.tab != key:
                    self.page = 0
                self.tab = key
                sfx("click", 0.5, 0.0)

    # Kademe rozetleri: eşyanın hangi kuşaktan olduğunu tek bakışta verir.
    TIER_BADGE = {1: ("I", (150, 186, 220)), 2: ("II", (150, 220, 170)),
                  3: ("III", (200, 160, 245)), 4: ("IV", (245, 205, 110)),
                  5: ("V", (255, 130, 70))}

    def _draw_card(self, surf, run, item, rect, mouse_pos, clicked, hellish, t, i):
        """Tek bir market kartı.

        Kart artık düz bir kutu değil: üstte kategori şeridi, ortada madalyon
        içinde simge, altta seviye boncukları ve altın renginde bir fiyat
        pastili var. Alınabilecek eşya nefes alır, alınamayan söner, tavana
        gelen yeşil bir mühür taşır — oyuncu listeye bakar bakmaz neyi
        alabileceğini görsün.
        """
        p = run.player
        unlocked = shop_item_unlocked(item, run.waves.wave, run.biome)
        hover = rect.collidepoint(mouse_pos) and unlocked
        lvl = p.shop_levels.get(item["key"], 0)
        maxed = lvl >= item.get("max", 999)
        cost = shop_item_cost(item, lvl)
        affordable = unlocked and not maxed and run.gold_wallet >= cost
        is_hell_item = bool(item.get("hell_only"))
        col = tuple(item["color"])
        pulse = 0.5 + 0.5 * math.sin(t * 3.0 + i * 0.8)

        # Hover'da kart hafifçe yukarı kalkar — listenin canlı durması için.
        if hover:
            rect = rect.move(0, -4)

        # ---- zemin: yukarıdan aşağı koyulaşan degrade ----
        if not unlocked:
            top_c = (24, 16, 20) if is_hell_item else (17, 18, 28)
            bot_c = (14, 10, 14) if is_hell_item else (11, 12, 19)
        elif is_hell_item:
            top_c = (74, 26, 20) if hover else (46, 18, 16)
            bot_c = (30, 12, 12)
        else:
            top_c = tuple(int(lerp(c, 255, 0.10)) for c in scale_col(col, 0.30)) if hover \
                else (26, 28, 44)
            bot_c = (14, 15, 24)
        bg = pygame.Surface(rect.size, pygame.SRCALPHA)
        for yy in range(rect.h):
            f = yy / max(1, rect.h - 1)
            pygame.draw.line(bg, (int(lerp(top_c[0], bot_c[0], f)),
                                  int(lerp(top_c[1], bot_c[1], f)),
                                  int(lerp(top_c[2], bot_c[2], f)), 246),
                             (0, yy), (rect.w, yy))
        mask = pygame.Surface(rect.size, pygame.SRCALPHA)
        pygame.draw.rect(mask, (255, 255, 255, 255), mask.get_rect(), border_radius=16)
        bg.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
        if hover and affordable:
            add_glow(surf, rect.centerx, rect.centery, rect.w * 0.78, col,
                     0.16 + 0.10 * pulse)
        surf.blit(bg, rect.topleft)

        # ---- çerçeve ----
        if not unlocked:
            edge_col = (58, 40, 40) if is_hell_item else (52, 54, 74)
        elif maxed:
            edge_col = GREEN
        elif item.get("legendary"):
            edge_col = GOLD
        elif affordable:
            edge_col = lighten(col, 0.22) if hover else col
        else:
            edge_col = scale_col(col, 0.45)
        pygame.draw.rect(surf, edge_col, rect, width=3 if (hover or maxed) else 2,
                         border_radius=16)

        # ---- üst şerit: kategori + kademe rozeti ----
        strip = pygame.Surface((rect.w - 22, 4), pygame.SRCALPHA)
        pygame.draw.rect(strip, (*edge_col, 210), strip.get_rect(), border_radius=2)
        surf.blit(strip, (rect.x + 11, rect.y + 8))
        badge, bcol = self.TIER_BADGE.get(item.get("tier", 1), ("I", TEXT_DIM))
        draw_text(surf, LX("cat." + item["cat"], SHOP_CATS.get(item["cat"], "")), (rect.x + 13, rect.y + 16), 9,
                  scale_col(edge_col, 0.95) if unlocked else (92, 88, 108),
                  bold=True, shadow=False)
        draw_text(surf, badge, (rect.right - 20, rect.y + 15), 11,
                  bcol if unlocked else (92, 88, 108), bold=True, center=True,
                  shadow=False)

        if is_hell_item and unlocked:
            # ergimiş kenar: kartın alt kenarında akkor bir şerit + kıvılcımlar
            molten = pygame.Surface((rect.w - 12, 5), pygame.SRCALPHA)
            for xx in range(molten.get_width()):
                k = 0.5 + 0.5 * math.sin(t * 3 + xx * 0.08 + i)
                pygame.draw.line(molten, (255, int(110 + 90 * k), 50, 190),
                                 (xx, 0), (xx, 5))
            surf.blit(molten, (rect.x + 6, rect.bottom - 8))
            for e in range(3):
                ph = (t * 0.9 + e * 0.33 + i * 0.2) % 1.0
                ex = rect.x + 16 + ((e * 73 + i * 37) % max(1, rect.w - 32))
                ey = rect.bottom - 10 - ph * 40
                blit_disc(surf, ex, ey, max(1.0, 2.6 * (1 - ph)), (255, 190, 90),
                          int(190 * (1 - ph)))

        # ---- madalyon + simge ----
        icon_col = col if unlocked else (74, 76, 92)
        icx, icy = rect.centerx, rect.y + 52
        if unlocked and not maxed:
            add_glow(surf, icx, icy, 34, icon_col, 0.24 + 0.14 * pulse)
        # v3.17: madalyonun BÜTÜN katmanları artık AYNI MERKEZDE. Eskiden
        # siyah taban (+2 aşağı) ile degrade disk (-4, -5 yukarı sol) farklı
        # merkezlerdeydi; siyah taban halkanın altından taşıyor ve simgenin
        # arkasında "oturmamış" ikinci bir daire gibi görünüyordu. Ayrı bir
        # siyah taban dairesine de gerek yok: degradenin kenarı zaten koyu.
        disc_grad(surf, icx, icy, 25, scale_col(icon_col, 0.50), (15, 16, 25), 9)
        ring_aa(surf, icx, icy, 25, icon_col, 2)
        # dönen kertikler — silah armalarıyla aynı dil
        if unlocked:
            for k_ in range(10):
                a = t * 0.5 + k_ * math.tau / 10
                thick_line(surf, (icx + math.cos(a) * 28, icy + math.sin(a) * 28),
                           (icx + math.cos(a) * (31 + 2 * pulse),
                            icy + math.sin(a) * (31 + 2 * pulse)),
                           1.2, scale_col(icon_col, 0.40 + 0.40 * pulse))
        draw_icon(surf, icx, icy, item["icon"] if unlocked else "shield",
                  lighten(icon_col, 0.25) if unlocked else icon_col,
                  19 if unlocked else 15)

        # ---- ad ----
        draw_text(surf, shop_name(item), (rect.centerx, rect.y + 88), 15,
                  TEXT if unlocked else TEXT_DIM, bold=True, center=True)
        if item.get("cursed"):
            draw_text(surf, L("ui.cursed"), (rect.centerx, rect.y + 105), 9, (235, 90, 110),
                      bold=True, center=True, shadow=False)
        elif item.get("legendary"):
            draw_text(surf, L("ui.legendary"), (rect.centerx, rect.y + 105), 9, GOLD,
                      bold=True, center=True, shadow=False)

        if not unlocked:
            if is_hell_item:
                draw_text(surf, L("ui.hell_only"), (rect.centerx, rect.y + 126), 12,
                          (255, 150, 90), center=True, shadow=False)
            else:
                need_wave = TIER_UNLOCK_WAVE.get(item["tier"], 0)
                draw_text(surf, L("ui.wave_unlock", need_wave), (rect.centerx, rect.y + 126),
                          12, GOLD_DIM, center=True, shadow=False)
            return

        # ---- açıklama ----
        off = 12 if (item.get("cursed") or item.get("legendary")) else 0
        for j, ln in enumerate(wrap_text(shop_desc(item), 11, rect.w - 26)[:3]):
            draw_text(surf, ln, (rect.centerx, rect.y + 110 + off + j * 14), 11,
                      TEXT_DIM, center=True, shadow=False)

        # ---- seviye göstergesi: tavanı olanlarda boncuk, sonsuzlarda sayı ----
        if not item.get("instant"):
            if item.get("endless"):
                draw_text(surf, L("ui.level_nocap", lvl),
                          (rect.centerx, rect.y + 168), 11, (206, 186, 126),
                          bold=True, center=True, shadow=False)
            else:
                mx = int(item.get("max", 1))
                pip_r, gap_p = 4, 11
                total = mx * gap_p - (gap_p - pip_r * 2)
                px0 = rect.centerx - total / 2 + pip_r
                for j in range(mx):
                    pc = col if j < lvl else (52, 54, 72)
                    circle_aa(surf, px0 + j * gap_p, rect.y + 166, pip_r, pc)
                    if j < lvl:
                        circle_aa(surf, px0 + j * gap_p - 1, rect.y + 165, pip_r * 0.45,
                                  lighten(col, 0.6))
                draw_text(surf, f"{lvl}/{mx}", (rect.centerx, rect.y + 176), 9,
                          TEXT_DIM, center=True, shadow=False)

        # ---- alt: fiyat pastili / MAKSİMUM mührü ----
        if maxed:
            mr = pygame.Rect(rect.x + 30, rect.y + 198, rect.w - 60, 24)
            pygame.draw.rect(surf, (18, 40, 26), mr, border_radius=12)
            pygame.draw.rect(surf, GREEN, mr, width=2, border_radius=12)
            draw_text(surf, L("ui.maxed"), mr.center, 12, GREEN, bold=True, center=True,
                      shadow=False)
        else:
            pcol = GOLD if affordable else (122, 98, 62)
            cost_txt = fmt_num(cost)
            # Pastil, içindeki "sikke + sayı" bloğunun GERÇEK genişliğine göre
            # kurulur; blok da pastilin tam ortasına oturur. Böylece 40 altın
            # da 128.500 altın da aynı biçimde ortalanmış görünür.
            block_w = coin_label_width(cost_txt, 17, 8)
            pill = pygame.Rect(0, 0, int(block_w) + 26, 26)
            pill.center = (rect.centerx, rect.y + 212)
            ps = pygame.Surface(pill.size, pygame.SRCALPHA)
            pygame.draw.rect(ps, (10, 9, 14, 190), ps.get_rect(), border_radius=13)
            surf.blit(ps, pill.topleft)
            pygame.draw.rect(surf, pcol if affordable else scale_col(pcol, 0.7), pill,
                             width=2, border_radius=13)
            draw_coin_label(surf, pill.centerx, pill.centery, cost_txt, pcol, 17,
                            icon_r=8)
            if hover and affordable:
                draw_text(surf, L("ui.buy"), (rect.centerx, rect.y + 190), 10,
                          lighten(col, 0.35), bold=True, center=True, shadow=False)
            elif not affordable:
                draw_text(surf, L("ui.no_gold"), (rect.centerx, rect.y + 190), 9,
                          (150, 110, 90), center=True, shadow=False)
            if hover and clicked and affordable:
                run.buy_shop_item(item["key"])

    # ---------------- ana çizim ----------------
    def draw_and_handle(self, surf, run, mouse_pos, clicked, t):
        hellish = self._hellish(run, self.tab)
        self._draw_backdrop(surf, hellish, t)
        self._draw_header(surf, run, hellish, t)
        self._draw_tabs(surf, run, mouse_pos, clicked, hellish, t)

        offers = [it for it in run.shop_offers if it["cat"] == self.tab]
        per_page = self.COLS * self.ROWS
        pages = max(1, (len(offers) + per_page - 1) // per_page)
        self.page = clamp(self.page, 0, pages - 1)
        shown = offers[self.page * per_page:(self.page + 1) * per_page]

        card_w, card_h = 216, 232
        gap_x, gap_y = 12, 10
        total_w = self.COLS * card_w + (self.COLS - 1) * gap_x
        start_x = VIRTUAL_W / 2 - total_w / 2
        start_y = 138

        for i, item in enumerate(shown):
            col_i, row = i % self.COLS, i // self.COLS
            rect = pygame.Rect(start_x + col_i * (card_w + gap_x),
                               start_y + row * (card_h + gap_y), card_w, card_h)
            self._draw_card(surf, run, item, rect, mouse_pos, clicked, hellish, t, i)

        if not offers:
            draw_text(surf, L("ui.cat_empty"),
                      (VIRTUAL_W / 2, start_y + 90), 18, TEXT_DIM, center=True)

        # --- sayfa okları (bir kategoride 10'dan fazla eşya varsa) ---
        if pages > 1:
            py = VIRTUAL_H - 92
            for dx in (-1, 1):
                br = pygame.Rect(int(VIRTUAL_W / 2 + dx * 118 - 20), py, 40, 30)
                can = (self.page > 0) if dx < 0 else (self.page < pages - 1)
                hov = br.collidepoint(mouse_pos) and can
                bcol = ((96, 36, 20) if hellish else (44, 48, 70)) if hov else (
                    (52, 22, 16) if hellish else (26, 28, 44))
                pygame.draw.rect(surf, bcol, br, border_radius=8)
                pygame.draw.rect(surf, (255, 120, 50) if hellish else PANEL_EDGE, br,
                                 width=2, border_radius=8)
                # Ok işareti yazı tipine bağlı kalmasın diye üçgen çiziliyor.
                acol = TEXT if can else (96, 90, 104)
                pygame.draw.polygon(surf, acol, [
                    (br.centerx + dx * 7, br.centery),
                    (br.centerx - dx * 5, br.centery - 8),
                    (br.centerx - dx * 5, br.centery + 8)])
                if hov and clicked:
                    self.page = clamp(self.page + dx, 0, pages - 1)
                    sfx("click", 0.5, 0.0)
            draw_text(surf, L("ui.page", self.page + 1, pages), (VIRTUAL_W / 2, py + 6), 15,
                      (255, 170, 110) if hellish else TEXT, bold=True, center=True)

        btn = Button((VIRTUAL_W / 2 - 130, VIRTUAL_H - 50, 260, 38), L("ui.close_b"), None,
                     color=(104, 44, 26) if hellish else (70, 76, 100),
                     hover_color=(150, 66, 36) if hellish else (95, 105, 140))
        btn.update(mouse_pos, 1 / 60)
        btn.draw(surf)
        return btn.rect.collidepoint(mouse_pos) and clicked


